/* Generated from the public v15.0.0 Beta Changelog (Northwood Studios). RU translation: fan-made. */
window.CL_ENTRIES=[null,{"k":"b","lv":0,"en":"Features may not be properly documented nor summarized yet.","ru":"Некоторые функции могут быть ещё не полностью задокументированы или описаны."},{"k":"b","lv":0,"en":"Features may be subject to change or to be completely removed.","ru":"Функции могут измениться или быть полностью удалены."},{"k":"b","lv":0,"en":"This is a public document and may be shared with any members of the community.","ru":"Это публичный документ, им можно делиться с любыми членами сообщества."},{"k":"b","lv":0,"en":"Slightly altered and slightly increased the size of hitboxes on all human classes.","ru":"Хитбоксы всех человеческих классов немного изменены и слегка увеличены."},{"k":"b","lv":0,"en":"Sneak speed for all human classes increased to 2.3 m/s (from 1.6).","ru":"Скорость скрытного шага у всех людей увеличена до 2,3 м/с (было 1,6)."},{"k":"b","lv":0,"en":"Improved human \"landing\" animations.","ru":"Улучшены анимации «приземления» людей."},{"k":"b","lv":1,"en":"This is the animation that plays after a human jumps, then touches the ground.","ru":"Это анимация, которая проигрывается, когда человек прыгает и касается земли."},{"k":"b","lv":0,"en":"Scientists now only spawn in LCZ Checkpoints.","ru":"Учёные теперь появляются только у КПП Лёгкой зоны."},{"k":"b","lv":0,"en":"One Facility Guard spawn is replaced with a Scientist spawn in the default spawn queue.","ru":"В стандартной очереди появления один спавн Охраны комплекса заменён на спавн Учёного."},{"k":"b","lv":1,"en":"This replaces the third player spawned in the round (that is currently spawned as a Guard) with a Scientist spawn.","ru":"Третий игрок раунда (который сейчас появляется Охранником) теперь будет Учёным."},{"k":"b","lv":0,"en":"Chaos Insurgents now share the same footsteps audio range as NTF.","ru":"Повстанцы Хаоса теперь слышны по шагам на том же расстоянии, что и МОГ."},{"k":"b","lv":0,"en":"Mini-wave spawn counts are now equal to 25% of the server’s population (from 20%).","ru":"Размер мини-волны теперь равен 25% от онлайна сервера (было 20%)."},{"k":"b","lv":1,"en":"This means an additional player should spawn in each mini wave on 25 player servers.","ru":"Это значит, что на серверах на 25 игроков в каждой мини-волне будет на одного игрока больше."},{"k":"b","lv":0,"en":"The winner of the round is now purely decided based on the last team standing.","ru":"Победитель раунда теперь определяется исключительно по последней выжившей команде."},{"k":"b","lv":1,"en":"Civilian escapes no longer have an affect on win conditions","ru":"Побеги гражданских больше не влияют на условия победы."},{"k":"b","lv":1,"en":"Stalemates still exist as a failsafe.","ru":"Ничья всё ещё существует как запасной вариант."},{"k":"b","lv":0,"en":"\"Forget About Your Fears\" is now louder and starts playing almost immediately when a human is the last one alive.","ru":"«Forget About Your Fears» теперь громче и начинает играть почти сразу, когда в живых остаётся последний человек."},{"k":"b","lv":0,"en":"Greatly improved performance of breaking glass particles.","ru":"Значительно улучшена производительность частиц бьющегося стекла."},{"k":"b","lv":0,"en":"Slightly expanded the framework for facial expressions.","ru":"Немного расширена система лицевой мимики."},{"k":"b","lv":1,"en":"Humans will change facial expressions when being grappled or having their eyes severed.","ru":"Люди меняют выражение лица, когда их хватают или когда им вырывают глаза."},{"k":"b","lv":1,"en":"Ragdolls will retain the previous facial expression of the player, slowly transitioning to a random death pose.","ru":"Рэгдоллы сохраняют прежнее выражение лица игрока, медленно переходя в случайную посмертную позу."},{"k":"b","lv":2,"en":"Dying from SCP-173 or bleeding from severed eyes uses a custom expression.","ru":"Смерть от SCP-173 или кровотечения из вырванных глаз использует особое выражение лица."},{"k":"b","lv":0,"en":"SCP hit animations will now play even if it doesn't deal any damage.","ru":"Анимации удара SCP теперь проигрываются, даже если урон не нанесён."},{"k":"b","lv":1,"en":"This is specifically noticeable on SCP-939.","ru":"Особенно это заметно у SCP-939."},{"k":"b","lv":0,"en":"SCP-106, SCP-173, and SCP-939 now have a new standard SCP head height of 1.95 meters.","ru":"SCP-106, SCP-173 и SCP-939 получили новую стандартную высоту головы SCP — 1,95 метра."},{"k":"b","lv":1,"en":"For reference, human head height is 1.8 meters and flamingo height is 1.2 meters.","ru":"Для сравнения: высота головы человека — 1,8 метра, а фламинго — 1,2 метра."},{"k":"b","lv":0,"en":"Dead Man Switch percentage health regen is now based on how many main spawn waves have spawned. Each wave spawned increases the percentage healed by 7.5%:","ru":"Процент восстановления здоровья от «Переключателя мертвеца» теперь зависит от количества появившихся основных волн. Каждая волна добавляет 7,5% к лечению:"},{"k":"b","lv":1,"en":"Zero waves spawned results in a 0% heal.","ru":"Ноль волн — лечение 0%."},{"k":"b","lv":1,"en":"One wave spawned results in a 7.5% heal.","ru":"Одна волна — лечение 7,5%."},{"k":"b","lv":2,"en":"Note: The above two should never happen naturally, but exist as a failsafe.","ru":"Примечание: два варианта выше не должны случаться естественным путём, они существуют как страховка."},{"k":"b","lv":1,"en":"Two waves spawned results in a 15% heal.","ru":"Две волны — лечение 15%."},{"k":"b","lv":1,"en":"Three waves spawned results in a 22.5% heal.","ru":"Три волны — лечение 22,5%."},{"k":"b","lv":1,"en":"Four waves spawned results in a 30% heal.","ru":"Четыре волны — лечение 30%."},{"k":"b","lv":1,"en":"The flat 250 HP heal is unaffected.","ru":"Фиксированное лечение на 250 HP не изменилось."},{"k":"b","lv":0,"en":"Dead Man Switch activation countdown is now paused while the Alpha Warhead is actively detonating.","ru":"Отсчёт активации «Переключателя мертвеца» ставится на паузу, пока идёт детонация Альфа-боеголовки."},{"k":"b","lv":0,"en":"Added a teammate outline to all SCPs within ~75 meter radius.","ru":"Все SCP теперь видят обводку союзников в радиусе ~75 метров."},{"k":"b","lv":1,"en":"The radius should be enough to see each other on opposite sides of a zone.","ru":"Этого радиуса должно хватать, чтобы видеть друг друга с противоположных концов зоны."},{"k":"b","lv":1,"en":"This doesn't apply to SCP-079, who doesn't see its teammate's outlines.","ru":"Это не касается SCP-079 — он не видит обводку союзников."},{"k":"b","lv":0,"en":"One minute after the Alpha Warhead's detonation, all living humans will become outlined red, and through the walls to the entire SCP team within a ~90 meters radius.","ru":"Через минуту после детонации Альфа-боеголовки все живые люди подсвечиваются красным, и вся команда SCP видит их сквозь стены в радиусе ~90 метров."},{"k":"b","lv":1,"en":"This lasts until the end of the round.","ru":"Это длится до конца раунда."},{"k":"b","lv":0,"en":"SCP Abilities (and their keybinds) are now displayed on their HUDs.","ru":"Способности SCP (и их клавиши) теперь отображаются на HUD."},{"k":"b","lv":1,"en":"Read more below, under \"UI Changes\".","ru":"Подробнее — ниже, в разделе «Изменения интерфейса»."},{"k":"b","lv":0,"en":"Added a new playable anomaly: SCP-953.","ru":"Добавлена новая играбельная аномалия: SCP-953."},{"k":"b","lv":0,"en":"SCP-953 specializes in deception and disruption. By utilising her abilities, she can integrate into groups, switch forms to adapt to new situations, and then unleash her powerful offensive abilities when revealed.","ru":"SCP-953 специализируется на обмане и дезорганизации. С помощью своих способностей она может внедряться в группы, менять облик под ситуацию, а после раскрытия — обрушивать мощные атакующие способности."},{"k":"b","lv":0,"en":"SCP-953’s abilities rely on Essence: a resource that is generated while being near, or taking damage from humans.","ru":"Способности SCP-953 завязаны на Эссенцию — ресурс, который накапливается, когда она находится рядом с людьми или получает от них урон."},{"k":"b","lv":1,"en":"Upon reaching 50% Essence, SCP-953 can reveal itself.","ru":"Набрав 50% Эссенции, SCP-953 может раскрыться."},{"k":"b","lv":0,"en":"SCP-953 begins the round in a disguised state amongst human classes.","ru":"SCP-953 начинает раунд замаскированной среди человеческих классов."},{"k":"b","lv":1,"en":"It cannot regenerate Essence for the first 90 seconds of the game, meaning it is unable to reveal itself for that time.","ru":"Первые 90 секунд игры она не может восстанавливать Эссенцию, то есть не может раскрыться в это время."},{"k":"b","lv":0,"en":"SCP-953 is given access to a disguise menu, where it can select between multiple forms or reveal itself.","ru":"SCP-953 получает меню маскировки, где можно выбрать один из обликов или раскрыться."},{"k":"b","lv":0,"en":"Upon reaching sufficient Essence, SCP-953 can use the Bewitch ability to violently reveal itself and inflict nearby humans with Hexed.","ru":"Набрав достаточно Эссенции, SCP-953 может применить способность «Порча» (Bewitch), чтобы яростно раскрыться и наложить на ближайших людей эффект «Проклятие» (Hexed)."},{"k":"b","lv":1,"en":"Hexed is a new status effect that disorients its victims and makes them more vulnerable to SCP-953’s attacks.","ru":"«Проклятие» — новый статус-эффект, который дезориентирует жертв и делает их уязвимее к атакам SCP-953."},{"k":"b","lv":0,"en":"When revealed, SCP-953 gains access to its offensive abilities.","ru":"После раскрытия SCP-953 получает доступ к атакующим способностям."},{"k":"b","lv":1,"en":"It can rapidly slash at nearby humans to regain Essence.","ru":"Она может быстро полосовать ближайших людей, восстанавливая Эссенцию."},{"k":"b","lv":1,"en":"SCP-953 can transition into a quadrupedal state that gives it enhanced mobility and an alternate attack: Pounce.","ru":"SCP-953 может перейти в четвероногую форму, которая даёт повышенную мобильность и альтернативную атаку — Прыжок (Pounce)."},{"k":"b","lv":1,"en":"Pounce must be charged and deals severe damage alongside rewarding SCP-953 with shield upon a successful hit.","ru":"Прыжок нужно заряжать; он наносит огромный урон и при попадании даёт SCP-953 щит."},{"k":"b","lv":1,"en":"Hitting Hexed targets with Pounce will Grapple them, allowing you to drag them around and then execute them.","ru":"Попадание Прыжком по «проклятой» цели хватает её — жертву можно тащить за собой, а затем казнить."},{"k":"c","lv":0,"en":"SCP-953 has finally arrived in a playable form. She will be iterated on throughout the beta with her art and audio passes being completed as time goes on. Please let us know what you think of her, as your feedback will be essential in making any adjustments!","ru":"SCP-953 наконец-то появилась в играбельном виде. На протяжении беты её будут дорабатывать — арт и звук ещё будут доделываться. Расскажите, что вы о ней думаете: ваш фидбек очень важен для будущих правок!"},{"k":"b","lv":0,"en":"Tuned down the intensity of SCP-079 audio filters to make users more intelligible.","ru":"Снижена интенсивность аудиофильтров SCP-079, чтобы игроков было лучше слышно."},{"k":"b","lv":0,"en":"Increased Tier-2 EXP requirement to 100 EXP (from 80).","ru":"Требование опыта для 2-го уровня увеличено до 100 EXP (было 80)."},{"k":"b","lv":0,"en":"Increased Tier-3 EXP requirement to 170 EXP (from 130).","ru":"Требование опыта для 3-го уровня увеличено до 170 EXP (было 130)."},{"k":"b","lv":1,"en":"In total 079 needs 270 EXP (from 210) to get to Tier-3.","ru":"Всего 079 теперь нужно 270 EXP (было 210), чтобы достичь 3-го уровня."},{"k":"b","lv":1,"en":"This means it needs to assist in the termination of at least 9 civilians/guards compared to the current 7.","ru":"Это значит, что ему нужно помочь в уничтожении минимум 9 гражданских/охранников вместо текущих 7."},{"k":"b","lv":0,"en":"Now starts the game with 0 AP.","ru":"Теперь начинает игру с 0 AP."},{"k":"b","lv":0,"en":"AP regen is now overhauled. 079 now regenerates proportionally to its max AP, so it will always take 40 seconds to regenerate to full AP from 0 across all tiers. Maximum AP values have also been increased to compensate.","ru":"Восстановление AP полностью переработано. Теперь 079 восстанавливает AP пропорционально максимуму — полное восстановление с нуля всегда занимает 40 секунд на любом уровне. Максимальный запас AP увеличен для компенсации."},{"k":"b","lv":1,"en":"Tier 1 AP: 100 max; 2.5/s regen.","ru":"Уровень 1: максимум 100 AP; 2,5/с."},{"k":"b","lv":1,"en":"Tier 2 AP: 120 max; 3/s regen","ru":"Уровень 2: максимум 120 AP; 3/с."},{"k":"b","lv":1,"en":"Tier 3 AP: 140 max; 3.5/s regen","ru":"Уровень 3: максимум 140 AP; 3,5/с."},{"k":"b","lv":1,"en":"Tier 4 AP: 160 max; 4/s regen.","ru":"Уровень 4: максимум 160 AP; 4/с."},{"k":"b","lv":1,"en":"Tier 5 AP: 200 max; 5/s regen.","ru":"Уровень 5: максимум 200 AP; 5/с."},{"k":"b","lv":0,"en":"Door locking a closed door now has a base AP drain rate of 10 AP/s.","ru":"Блокировка закрытой двери теперь имеет базовый расход 10 AP/с."},{"k":"b","lv":1,"en":"This is on top of the exponential AP drain.","ru":"Это в дополнение к экспоненциальному расходу AP."},{"k":"b","lv":0,"en":"Door locking cooldown increase per second locked is now 2.5s per second locked (from 0.5s).","ru":"Прирост перезарядки блокировки дверей за каждую секунду блокировки теперь 2,5 с (было 0,5 с)."},{"k":"b","lv":1,"en":"The base cooldown of 3 seconds is unchanged.","ru":"Базовая перезарядка в 3 секунды не изменилась."},{"k":"b","lv":0,"en":"Lockdown cost increased to 120 (from 100).","ru":"Стоимость Локдауна увеличена до 120 (было 100)."},{"k":"b","lv":0,"en":"Lockdown now pauses regen on Tier 5 instead of just halving it.","ru":"Локдаун на 5-м уровне теперь останавливает восстановление, а не просто уменьшает его вдвое."},{"k":"b","lv":0,"en":"Default door interaction cost increased to 10 AP (from 5).","ru":"Базовая стоимость взаимодействия с дверью увеличена до 10 AP (было 5)."},{"k":"b","lv":0,"en":"Speakers no longer halve regeneration while in use.","ru":"Динамики больше не уменьшают восстановление вдвое при использовании."},{"k":"b","lv":0,"en":"Added icons to SCP-079's map for generators.","ru":"На карту SCP-079 добавлены значки генераторов."},{"k":"b","lv":1,"en":"This icon is placed based on the generator's position on the map. Similar to player indicators.","ru":"Значок ставится по позиции генератора на карте — так же, как индикаторы игроков."},{"k":"b","lv":0,"en":"Lockdown is no longer available on Surface Zone.","ru":"Локдаун больше недоступен на Поверхности."},{"k":"b","lv":0,"en":"SCP-079 will now be able to survive the Alpha Warhead detonation if it has reached Access Tier 5 and at least one SCP teammate remains post-detonation.","ru":"SCP-079 теперь может пережить детонацию Альфа-боеголовки, если он достиг 5-го уровня доступа и после взрыва остался хотя бы один союзник-SCP."},{"k":"b","lv":1,"en":"It will be locked to the Surface Zone cameras exclusively, and its map will only display Surface Zone.","ru":"Он будет ограничен только камерами Поверхности, а его карта будет показывать только Поверхность."},{"k":"b","lv":1,"en":"If no SCP teammates survive the detonation, SCP-079 will still be terminated.","ru":"Если ни один союзник-SCP не пережил детонацию, SCP-079 всё равно будет уничтожен."},{"k":"c","lv":0,"en":"SCP-079 was largely absent from all the balance changes done in the 14.0 development cycle. In this pass, we have focused on further emphasising resource management within its kit. SCP-079 players should now, ideally, have to think more about how they save and spend their Auxiliary Power. These changes are experimental, so do let us know how you feel about them in practice.","ru":"SCP-079 почти не затронули балансные изменения цикла 14.0. В этот раз мы сосредоточились на управлении ресурсами в его наборе. Теперь игрокам за SCP-079 в идеале придётся больше думать о том, как копить и тратить вспомогательную энергию. Изменения экспериментальные, так что расскажите, как они ощущаются на практике."},{"k":"b","lv":0,"en":"Now has a new damage hitbox that is accurate to its model.","ru":"Получил новый хитбокс урона, точно соответствующий модели."},{"k":"b","lv":1,"en":"SCP-096's hitboxes now increase in size by 1.5x when Enraged.","ru":"В Ярости хитбоксы SCP-096 увеличиваются в 1,5 раза."},{"k":"b","lv":2,"en":"This is done to compensate for its new tighter hitbox.","ru":"Это компенсирует новый, более плотный хитбокс."},{"k":"b","lv":1,"en":"Dev Note: The old hitbox was much larger than necessary and made SCP-096 take much more damage than other SCPs.","ru":"Заметка разработчиков: старый хитбокс был гораздо больше необходимого, и SCP-096 получал намного больше урона, чем другие SCP."},{"k":"b","lv":0,"en":"As a result of the above change, 096’s HP has been reverted back to 2500 (from 3000).","ru":"В результате здоровье 096 возвращено к 2500 (было 3000)."},{"k":"b","lv":0,"en":"Increased Melee Attack cooldown to 0.6 seconds (from 0.5).","ru":"Перезарядка ближней атаки увеличена до 0,6 с (было 0,5)."},{"k":"b","lv":0,"en":"SCP-096 now has a special camera height of 2.1 meters.","ru":"У SCP-096 теперь особая высота камеры — 2,1 метра."},{"k":"b","lv":0,"en":"Slightly adjusted scaling of 096's volume over distance.","ru":"Немного изменено затухание громкости 096 с расстоянием."},{"k":"b","lv":0,"en":"Corroding no longer pauses stamina.","ru":"Коррозия больше не останавливает выносливость."},{"k":"b","lv":0,"en":"Corroding now has a vignette to indicate that it is active.","ru":"У Коррозии появилась виньетка, показывающая, что она активна."},{"k":"b","lv":1,"en":"Note: This also applies to Pocket Corroding.","ru":"Примечание: это касается и Коррозии в Карманном измерении."},{"k":"b","lv":0,"en":"Corroded victims can now be seen outlined by SCP-106.","ru":"SCP-106 теперь видит обводку жертв, поражённых Коррозией."},{"k":"b","lv":1,"en":"Within a 25 meter range.","ru":"В радиусе 25 метров."},{"k":"b","lv":1,"en":"Colored dark purple.","ru":"Тёмно-фиолетовый цвет."},{"k":"b","lv":1,"en":"Fades over distance, can't be seen through walls.","ru":"Затухает с расстоянием, не видна сквозь стены."},{"k":"b","lv":0,"en":"Traumatized victims can now be seen outlined by SCP-106.","ru":"SCP-106 теперь видит обводку травмированных жертв."},{"k":"b","lv":1,"en":"Within a 30 meter range.","ru":"В радиусе 30 метров."},{"k":"b","lv":1,"en":"Colored cyan.","ru":"Голубой цвет."},{"k":"b","lv":1,"en":"Can be seen through walls.","ru":"Видна сквозь стены."},{"k":"b","lv":1,"en":"Overrides other outlines.","ru":"Перекрывает другие обводки."},{"k":"b","lv":0,"en":"SCP-106 can no longer be flashed while stalking.","ru":"SCP-106 больше нельзя ослепить светошумовой во время Преследования."},{"k":"b","lv":0,"en":"Cardiac Arrest victims can now be seen outlined by SCP-049.","ru":"SCP-049 теперь видит обводку жертв с Остановкой сердца."},{"k":"b","lv":1,"en":"Within a 25 meter range.","ru":"В радиусе 25 метров."},{"k":"b","lv":1,"en":"Colored purple.","ru":"Фиолетовый цвет."},{"k":"b","lv":1,"en":"Fades over distance, can't be seen through walls.","ru":"Затухает с расстоянием, не видна сквозь стены."},{"k":"b","lv":0,"en":"Bloodlust now begins building up speed 0.3 seconds after spotting a human (from 1 second).","ru":"Жажда крови теперь начинает набирать скорость через 0,3 с после обнаружения человека (было 1 с)."},{"k":"b","lv":0,"en":"Bloodlust now increases speed by 0.125 m/s per tick (from 0.05).","ru":"Жажда крови теперь увеличивает скорость на 0,125 м/с за тик (было 0,05)."},{"k":"b","lv":1,"en":"In exchange it also decays faster at a rate of 0.25 m/s (from 0.1).","ru":"Взамен она и спадает быстрее — 0,25 м/с (было 0,1)."},{"k":"b","lv":0,"en":"Slightly increased the size of SCP-049-2's head hitbox.","ru":"Немного увеличен хитбокс головы SCP-049-2."},{"k":"b","lv":0,"en":"Raised model slightly to fix it clipping into the ground.","ru":"Модель немного приподнята, чтобы она не проваливалась в пол."},{"k":"b","lv":0,"en":"Reduced Claw range to 1.54 meters (from 1.8).","ru":"Дальность удара когтями уменьшена до 1,54 метра (было 1,8)."},{"k":"b","lv":0,"en":"Decreased 939’s attack delay to 0.15s (from 0.25s).","ru":"Задержка атаки 939 уменьшена до 0,15 с (было 0,25 с)."},{"k":"b","lv":1,"en":"Note: The attack delay is separate from the attack cooldown. The delay measures the time it takes for the shot to land after pressing M1.","ru":"Примечание: задержка атаки — это не перезарядка. Задержка — время от нажатия ЛКМ до того, как удар «долетит»."},{"k":"b","lv":0,"en":"If a player moves into an Amnestic Cloud created by SCP-939, any outlines that they could see are removed for the duration they are afflicted with the Amnesia status effect.","ru":"Если игрок заходит в Амнестическое облако SCP-939, все видимые ему обводки пропадают на время действия эффекта Амнезии."},{"k":"b","lv":0,"en":"Made the following Environmental Mimicry sounds more accurate to their actual counterparts:","ru":"Следующие звуки Мимикрии окружения стали точнее соответствовать оригиналам:"},{"k":"b","lv":1,"en":"All Firearms","ru":"Все виды огнестрельного оружия"},{"k":"b","lv":1,"en":"SCP-049 Footsteps","ru":"Шаги SCP-049"},{"k":"b","lv":1,"en":"SCP-096 Crying","ru":"Плач SCP-096"},{"k":"b","lv":1,"en":"SCP-106 Footsteps","ru":"Шаги SCP-106"},{"k":"b","lv":1,"en":"SCP-939 Footsteps","ru":"Шаги SCP-939"},{"k":"b","lv":1,"en":"Chaos Insurgency Footsteps","ru":"Шаги Повстанцев Хаоса"},{"k":"b","lv":1,"en":"NTF Footsteps","ru":"Шаги МОГ"},{"k":"b","lv":0,"en":"SCP-079’s Mimicry is now that of an HCZ Door opening or closing.","ru":"Мимикрия SCP-079 теперь — звук открытия/закрытия двери Тяжёлой зоны."},{"k":"b","lv":0,"en":"Firearm Mimicry sounds now lasts longer.","ru":"Звуки мимикрии выстрелов теперь длятся дольше."},{"k":"b","lv":0,"en":"Mimic Points can now be placed and destroyed by clicking M2.","ru":"Точки мимикрии теперь можно ставить и уничтожать нажатием ПКМ."},{"k":"b","lv":0,"en":"SCP-939 can now interact with the intercom system.","ru":"SCP-939 теперь может пользоваться интеркомом."},{"k":"b","lv":1,"en":"Using a voice line triggers the intercom.","ru":"Использование голосовой реплики активирует интерком."},{"k":"b","lv":1,"en":"Not using a voice chat for 3 seconds or walking away cancels the transmission.","ru":"Если 3 секунды не говорить или отойти — трансляция прервётся."},{"k":"b","lv":0,"en":"SCP-939 now plays the Claw animation when swinging regardless of whether it hit something.","ru":"SCP-939 теперь проигрывает анимацию удара когтями при каждом взмахе, даже если ни во что не попал."},{"k":"b","lv":0,"en":"All human classes can see a small outline of the item they are attempting to pick up.","ru":"Все человеческие классы видят небольшую обводку предмета, который пытаются подобрать."},{"k":"b","lv":1,"en":"This can be disabled with the new Pickup Outlines video setting.","ru":"Это можно отключить новой видеонастройкой «Обводка подбираемых предметов»."},{"k":"b","lv":0,"en":"Added SCP-018 inspect animation & sound effect.","ru":"Добавлены анимация осмотра и звук для SCP-018."},{"k":"b","lv":0,"en":"Flashbangs can no longer apply the Flashed effect if the player already has the effect.","ru":"Светошумовые гранаты больше не накладывают эффект Ослепления, если он уже есть у игрока."},{"k":"b","lv":0,"en":"Cards now have a short description of their purposes underneath each of their inventory names like in PEARS 5:","ru":"У карт-ключей под названием в инвентаре появилось короткое описание назначения, как в PEARS 5:"},{"k":"b","lv":1,"en":"Janitor Card - Opens SCP-914.","ru":"Карта уборщика — открывает SCP-914."},{"k":"b","lv":1,"en":"Scientist Card - Opens SCP Containment Chambers.","ru":"Карта учёного — открывает камеры содержания SCP."},{"k":"b","lv":1,"en":"Zone Manager Card - Opens Checkpoints and SCP-914.","ru":"Карта менеджера зоны — открывает КПП и SCP-914."},{"k":"b","lv":1,"en":"Research Supervisor Card - Opens SCP Item Pedestals and Checkpoints.","ru":"Карта научного руководителя — открывает пьедесталы SCP-предметов и КПП."},{"k":"b","lv":1,"en":"Facility Manager Card - Opens SCP Weapon Lockers and Warhead Panel.","ru":"Карта менеджера комплекса — открывает оружейные шкафы SCP и панель боеголовки."},{"k":"b","lv":1,"en":"Facility Guard Card - General Low Tier Access.","ru":"Карта охраны комплекса — общий доступ низкого уровня."},{"k":"b","lv":1,"en":"NTF Operative Card - General Access.","ru":"Карта оперативника МОГ — общий доступ."},{"k":"b","lv":1,"en":"Chaos Insurgency Card - General and Experimental Weapon Access.","ru":"Карта Повстанцев Хаоса — общий доступ и доступ к экспериментальному оружию."},{"k":"b","lv":1,"en":"NTF Captain Card - General and Experimental Weapon Access.","ru":"Карта капитана МОГ — общий доступ и доступ к экспериментальному оружию."},{"k":"b","lv":0,"en":"Radio now has only 2 frequency ranges: Short and Long.","ru":"У рации теперь только 2 диапазона частот: Короткий и Длинный."},{"k":"b","lv":0,"en":"Radio volume can now be adjusted by scrolling the mouse wheel while holding a radio.","ru":"Громкость рации теперь можно менять колёсиком мыши, держа её в руках."},{"k":"b","lv":1,"en":"You can also adjust this on the user settings in the menu.","ru":"Также это можно настроить в пользовательских настройках в меню."},{"k":"b","lv":0,"en":"Default SCP item inventory limit reduced to two (from three).","ru":"Стандартный лимит SCP-предметов в инвентаре уменьшен до двух (было три)."},{"k":"b","lv":0,"en":"Putting SCP-207 on 1:1 now only has a 50% chance to produce Anti-SCP-207.","ru":"SCP-207 в режиме 1:1 теперь лишь с шансом 50% превращается в Anti-SCP-207."},{"k":"b","lv":1,"en":"The other 50% chance it will be destroyed.","ru":"В остальных 50% случаев она будет уничтожена."},{"k":"b","lv":0,"en":"Spawn chance per round increased to 25% (from 15%).","ru":"Шанс появления за раунд увеличен до 25% (было 15%)."},{"k":"b","lv":0,"en":"Anti-SCP-207 now only regenerates up to 40 AHP (from 75).","ru":"Anti-SCP-207 теперь восстанавливает максимум до 40 AHP (было 75)."},{"k":"b","lv":0,"en":"Anti-SCP-207 now has a new weapon handling and item usage debuff which makes actions more sluggish:","ru":"Anti-SCP-207 получила новый дебафф обращения с оружием и предметами — действия становятся более вялыми:"},{"k":"b","lv":1,"en":"Medical item usage time is now 25% slower.","ru":"Использование медицинских предметов на 25% медленнее."},{"k":"b","lv":1,"en":"Draw time on firearms and medical items is now 20% slower.","ru":"Доставание оружия и медпредметов на 20% медленнее."},{"k":"b","lv":1,"en":"Reload time is now 30% slower.","ru":"Перезарядка на 30% медленнее."},{"k":"b","lv":1,"en":"ADS enter/exit time is now 20% slower.","ru":"Вход/выход из прицеливания на 20% медленнее."},{"k":"b","lv":0,"en":"The Anti-SCP-207 and SCP-207 explosion delay is decreased to 0.3 seconds (from 1.05s).","ru":"Задержка взрыва Anti-SCP-207 и SCP-207 уменьшена до 0,3 с (было 1,05 с)."},{"k":"b","lv":0,"en":"Significantly increased the volume of the death-save audio.","ru":"Значительно увеличена громкость звука спасения от смерти."},{"k":"c","lv":0,"en":"Anti-Cola has proved itself to be a troublesome item to play against. We are moderately curbing its tankiness while also introducing a new downside to make the user worse in sustained engagements. On top of that, we are also adjusting its accessibility.","ru":"Анти-кола оказалась очень неприятным предметом для противника. Мы умеренно урезаем её живучесть и добавляем новый минус, который делает владельца слабее в затяжных перестрелках. Кроме того, мы меняем её доступность."},{"k":"b","lv":0,"en":"Players that are considered standing-still will no longer produce an orb to the 1344 user.","ru":"Игроки, которые стоят на месте, больше не создают сферу для пользователя SCP-1344."},{"k":"b","lv":1,"en":"The player must not have moved in the past two seconds.","ru":"Игрок не должен был двигаться последние две секунды."},{"k":"b","lv":2,"en":"Note: This is accomplished via a similar system used to determine if 106 is moving with Vigor regeneration: if the player stays within a small radius for two seconds they are considered not moving.","ru":"Примечание: используется система, похожая на проверку движения 106 для восстановления Бодрости: если игрок остаётся в небольшом радиусе две секунды — он считается неподвижным."},{"k":"b","lv":1,"en":"If the player has been standing still for more than 30 seconds, they will produce an orb again.","ru":"Если игрок стоит на месте больше 30 секунд, сфера снова появляется."},{"k":"b","lv":0,"en":"Updated the inventory description to match this change.","ru":"Описание в инвентаре обновлено под это изменение."},{"k":"b","lv":0,"en":"Added the ability to copy & paste attachment codes inside (and outside!) of the game.","ru":"Добавлена возможность копировать и вставлять коды обвесов в игре (и вне её!)."},{"k":"b","lv":1,"en":"You can do this by using the new buttons on in-game Workstations.","ru":"Для этого на игровых Верстаках появились новые кнопки."},{"k":"b","lv":0,"en":"Revamped scopes across all firearms:","ru":"Прицелы на всём оружии переработаны:"},{"k":"b","lv":1,"en":"Sniper Scopes now zoom in 3.5x (from 6.0x).","ru":"Снайперские прицелы теперь дают увеличение 3,5x (было 6,0x)."},{"k":"b","lv":1,"en":"Night Vision Scopes now zoom in 2.0x (from 1.0x).","ru":"Прицелы ночного видения теперь дают увеличение 2,0x (было 1,0x)."},{"k":"b","lv":1,"en":"Night Vision Scope visual effects are now less desaturated and dark.","ru":"Эффекты прицела ночного видения стали менее обесцвеченными и тёмными."},{"k":"b","lv":1,"en":"Reduced intensity of Sniper Scope post processing.","ru":"Снижена интенсивность постобработки снайперского прицела."},{"k":"b","lv":1,"en":"Scopes now take up a greater amount of the player’s screen.","ru":"Прицелы теперь занимают большую часть экрана."},{"k":"b","lv":1,"en":"Scopes have their recoil animation on each shot significantly reduced.","ru":"Анимация отдачи прицела при каждом выстреле значительно уменьшена."},{"k":"b","lv":1,"en":"On the E11-SR and AK, the Sniper Scope will reduce ADS recoil by 5%.","ru":"На E11-SR и AK снайперский прицел снижает отдачу при прицеливании на 5%."},{"k":"b","lv":1,"en":"All Sniper Scopes now increase time to ADS by +30% (same as the E11-SR’s).","ru":"Все снайперские прицелы увеличивают время прицеливания на +30% (как у E11-SR)."},{"k":"b","lv":1,"en":"Sniper Scopes on Rifles now weigh more.","ru":"Снайперские прицелы на винтовках теперь весят больше."},{"k":"b","lv":0,"en":"Reduced intensity of ADS recoil animations on each shot for each firearm.","ru":"Снижена интенсивность анимаций отдачи при прицеливании на всём оружии."},{"k":"b","lv":1,"en":"Note: LMGs still have significant shaking.","ru":"Примечание: пулемёты всё ещё заметно трясёт."},{"k":"b","lv":0,"en":"Decreased ADS recoil reduction for the Logicer, FR-MG-0, Shotgun, and Crossvec.","ru":"Уменьшено снижение отдачи при прицеливании у Logicer, FR-MG-0, Дробовика и Crossvec."},{"k":"b","lv":0,"en":"Dot Sights across all guns are now equivalent to Holo Sight weights.","ru":"Коллиматорные прицелы (Dot Sight) на всём оружии теперь весят как голографические."},{"k":"b","lv":0,"en":"Reduced ADS head bobbing across all guns.","ru":"Уменьшено покачивание головы при прицеливании на всём оружии."},{"k":"b","lv":0,"en":"Inaccuracy gained when jumping increased to +7° (from +3°).","ru":"Неточность при прыжке увеличена до +7° (было +3°)."},{"k":"c","lv":0,"en":"We have decided to try and make firearm scopes easier and more practical to use. We hope that these changes, alongside other improvements done to aiming, will make aiming down sights a more viable, niche alternative to hip-fire playstyles without nerfing hip-firing in the process.","ru":"Мы решили сделать прицелы проще и практичнее. Надеемся, что эти изменения вместе с другими улучшениями прицеливания сделают стрельбу через прицел жизнеспособной нишевой альтернативой стрельбе от бедра — при этом не ослабляя стрельбу от бедра."},{"k":"b","lv":0,"en":"Firearms will now drop additional visual clutter during gameplay:","ru":"Оружие теперь роняет дополнительный визуальный «мусор» во время игры:"},{"k":"b","lv":0,"en":"Repeaters with detachable magazines now drop them during combat reload.","ru":"Оружие с отъёмными магазинами роняет их при боевой перезарядке."},{"k":"b","lv":0,"en":"Revolver drops the speedloader during any reload animation which involves using it.","ru":"Револьвер роняет спидлоадер во всех анимациях перезарядки, где он используется."},{"k":"b","lv":0,"en":"Pumping the Shotgun ejects the empty shells.","ru":"При передёргивании Дробовика вылетают пустые гильзы."},{"k":"b","lv":0,"en":"Disruptor ejects the battery during reload. If the reload is interrupted by dropping/holstering it, it won't drop another battery until it is fired again.","ru":"Дисраптор выбрасывает батарею при перезарядке. Если перезарядку прервать (выбросить/убрать оружие), новая батарея не выпадет, пока он снова не выстрелит."},{"k":"b","lv":0,"en":"This is a small visual detail, not intended to affect balance, so it contains several limitations for the sake of keeping things optimized:","ru":"Это мелкая визуальная деталь, которая не должна влиять на баланс, поэтому ради оптимизации у неё есть ограничения:"},{"k":"b","lv":1,"en":"Similar to bullet holes and blood decals, storage is handled client-side. As a result:","ru":"Как и дырки от пуль и пятна крови, всё это хранится на стороне клиента. Поэтому:"},{"k":"b","lv":1,"en":"Physics is not synchronized between players. That means clutter can bounce in random directions and end up landing in slightly different locations for different players.","ru":"Физика не синхронизируется между игроками — «мусор» может отскакивать в случайные стороны и лежать в разных местах у разных игроков."},{"k":"b","lv":1,"en":"Joining the server mid-round won't cause the previously dropped clutter to appear.","ru":"Если зайти на сервер посреди раунда, ранее выпавший «мусор» не появится."},{"k":"b","lv":1,"en":"There is a soft limit of 25 instances, shared by all kinds of dropped clutter. If the number of instances exceeds that limit, the oldest instance begins to decay (fade away into transparency over the course of a few seconds).","ru":"Есть мягкий лимит в 25 объектов на все виды «мусора». Если он превышен, самые старые объекты начинают исчезать (растворяться за несколько секунд)."},{"k":"b","lv":1,"en":"The same decay happens to instances that have existed for longer than two minutes, even if the soft limit has not been reached.","ru":"То же происходит с объектами, которые существуют дольше двух минут, даже если лимит не достигнут."},{"k":"b","lv":0,"en":"Total pellet fired count increased to 13 (from 12); maximum pellets that can hit increased to 9 (from 8).","ru":"Общее число выпускаемых дробин увеличено до 13 (было 12); максимум попадающих дробин — 9 (было 8)."},{"k":"b","lv":1,"en":"Due to this, individual pellet damage has been reduced to 9.1 (from 11.3). This results in a total damage of 91 (from 90.4).","ru":"Поэтому урон одной дробины снижен до 9,1 (было 11,3). Общий урон — 91 (было 90,4)."},{"k":"b","lv":1,"en":"In accordance with the above change, Double Shot pellet count increased to 10 (from eight).","ru":"В соответствии с этим число дробин при Двойном выстреле увеличено до 10 (было восемь)."},{"k":"b","lv":0,"en":"Base penetration increased to 50% (from 40%).","ru":"Базовое пробитие увеличено до 50% (было 40%)."},{"k":"b","lv":1,"en":"Due to this Extended Barrel penetration bonus reduced to +30% (from +50%).","ru":"Поэтому бонус пробития от Удлинённого ствола снижен до +30% (было +50%)."},{"k":"b","lv":0,"en":"Damage falloff now starts at 11 meters (from 3.64).","ru":"Падение урона теперь начинается с 11 метров (было 3,64)."},{"k":"b","lv":0,"en":"Widened pellet spread but reduced base pellet randomness.","ru":"Разброс дробин стал шире, но базовая случайность дробин снижена."},{"k":"b","lv":0,"en":"Increased vertical recoil.","ru":"Увеличена вертикальная отдача."},{"k":"b","lv":0,"en":"Made the predefined pellet spread pattern more uniform.","ru":"Заданный паттерн разброса дробин стал равномернее."},{"k":"b","lv":0,"en":"Revamped how hitmarkers on the Shotgun function:","ru":"Переработаны хитмаркеры Дробовика:"},{"k":"b","lv":1,"en":"The player will always receive a hitmarker regardless of the amount of pellets that land.","ru":"Хитмаркер появляется всегда, сколько бы дробин ни попало."},{"k":"b","lv":1,"en":"The hitmarker scales in size with each pellet that lands.","ru":"Размер хитмаркера растёт с каждой попавшей дробиной."},{"k":"b","lv":1,"en":"If all pellets that are able to deal damage land, the player receives an extra-large hitmarker.","ru":"Если попали все дробины, способные нанести урон, — появляется особо крупный хитмаркер."},{"k":"b","lv":0,"en":"Made the pumping animation slightly faster.","ru":"Анимация передёргивания стала чуть быстрее."},{"k":"c","lv":0,"en":"The Shotgun has received many adjustments to try and make the weapon more consistent and powerful within individual hallways. Like some other tweaks included, it is experimental and highly subject to change.","ru":"Дробовик получил множество правок, чтобы стать стабильнее и сильнее в отдельных коридорах. Как и некоторые другие изменения, это эксперимент, и всё может сильно поменяться."},{"k":"b","lv":0,"en":"Reduced and simplified horizontal recoil.","ru":"Горизонтальная отдача уменьшена и упрощена."},{"k":"b","lv":0,"en":"Increased vertical recoil kick.","ru":"Увеличен вертикальный подброс."},{"k":"b","lv":0,"en":"Reduced recoil increase from the Muzzle Booster to +17.5% (from +25%).","ru":"Прирост отдачи от Дульного ускорителя снижен до +17,5% (было +25%)."},{"k":"b","lv":0,"en":"Significantly reduced draw time penalty for both the Grip and Stock attachments.","ru":"Значительно уменьшен штраф ко времени доставания от рукояти и приклада."},{"k":"b","lv":0,"en":"Buckshot round attachment damage falloff now starts at 10 meters (from 3.5).","ru":"Падение урона у картечных патронов теперь начинается с 10 метров (было 3,5)."},{"k":"b","lv":1,"en":"It falls off until 50 meters (from 45).","ru":"Урон падает до 50 метров (было 45)."},{"k":"b","lv":0,"en":"Decreased overall pellet spread.","ru":"Уменьшен общий разброс дробин."},{"k":"b","lv":0,"en":"Slightly increased vertical recoil.","ru":"Немного увеличена вертикальная отдача."},{"k":"b","lv":0,"en":"Crossvec retracted stock attachment now gives +25% hip-fire accuracy.","ru":"Сложенный приклад Crossvec теперь даёт +25% к точности от бедра."},{"k":"b","lv":0,"en":"In exchange the ADS recoil penalty on the attachment is now +60% (from +50%).","ru":"Взамен штраф к отдаче при прицеливании от этого обвеса теперь +60% (было +50%)."},{"k":"b","lv":0,"en":"Reduced maximum ammo capacity to 50 (from 60).","ru":"Максимальный запас патронов уменьшен до 50 (было 60)."},{"k":"b","lv":0,"en":"Ammo regen delay is now consistently two seconds across all tiers.","ru":"Задержка восстановления патронов теперь всегда 2 секунды на всех уровнях."},{"k":"b","lv":0,"en":"Ammo bonus on kill reduced to +10 (from +15).","ru":"Бонус патронов за убийство снижен до +10 (было +15)."},{"k":"b","lv":0,"en":"Attack cooldown increased to 0.66s (from 0.6s).","ru":"Перезарядка атаки увеличена до 0,66 с (было 0,6 с)."},{"k":"b","lv":0,"en":"Secondary target damage reduced to 20 (from 25).","ru":"Урон по второстепенным целям снижен до 20 (было 25)."},{"k":"b","lv":0,"en":"Blurred duration for revived players decreased to one second (from three).","ru":"Длительность размытия у воскрешённых игроков уменьшена до одной секунды (было три)."},{"k":"b","lv":0,"en":"Revived player maximum HP reduction removed, meaning they now spawn with a full 100 maximum HP (from 75).","ru":"Снижение максимального HP у воскрешённых убрано — теперь они появляются с полными 100 HP (было 75)."},{"k":"b","lv":1,"en":"The lower cap on AHP is still retained.","ru":"Нижний предел AHP сохранён."},{"k":"b","lv":0,"en":"Increased the thickness of the Primary Fire beam to 0.55 meters (from 0.2 meters).","ru":"Толщина луча основного огня увеличена до 0,55 метра (было 0,2 метра)."},{"k":"b","lv":1,"en":"For reference, the Charge Fire beam is 0.65 meters in thickness.","ru":"Для сравнения: луч заряженного выстрела — 0,65 метра."},{"k":"b","lv":0,"en":"Primary Fire mode range increased to seven meters (from six).","ru":"Дальность основного огня увеличена до семи метров (было шесть)."},{"k":"b","lv":0,"en":"Changed explosion visuals of players dying by Micro-HID overcharge to more closely match our original vision.","ru":"Визуал взрыва игроков, погибших от перегрузки Micro-HID, изменён ближе к изначальной задумке."},{"k":"b","lv":0,"en":"The Micro-HID now grants large hitmarkers when successfully hitting targets.","ru":"Micro-HID теперь показывает крупные хитмаркеры при успешном попадании."},{"k":"b","lv":0,"en":"Charge wind-up audio radius increased by 2.0x.","ru":"Радиус звука замаха для рывка увеличен в 2 раза."},{"k":"b","lv":0,"en":"Moved Particle Disruptor's ammo warning message on 4th shot.","ru":"Предупреждение о патронах у Дисраптора перенесено на 4-й выстрел."},{"k":"b","lv":1,"en":"This warning is now also positioned lower, and more transparent for easier aiming.","ru":"Это предупреждение теперь ниже на экране и прозрачнее, чтобы не мешать целиться."},{"k":"b","lv":0,"en":"Particle Disruptor now also remembers its firing state when dropped.","ru":"Дисраптор теперь запоминает режим стрельбы, если его выбросить."},{"k":"b","lv":0,"en":"The text on the Particle Disruptor's display is now translatable.","ru":"Текст на дисплее Дисраптора теперь переводится."},{"k":"b","lv":0,"en":"Introduced a completely new design for the Main Menu.","ru":"Главное меню получило полностью новый дизайн."},{"k":"b","lv":1,"en":"Note: For now, the Operational Guide will be disabled until it is properly reimplemented.","ru":"Примечание: пока что Оперативное руководство отключено, пока его не реализуют заново."},{"k":"b","lv":0,"en":"Implemented a new main menu background and transition system, cycling between different rooms.","ru":"Новый фон главного меню и система переходов, переключающаяся между разными комнатами."},{"k":"b","lv":0,"en":"News now are formatted with their own custom heading and styling.","ru":"Новости теперь оформлены с собственными заголовками и стилями."},{"k":"b","lv":1,"en":"These are generated automatically by translating Steam's BBCode into our own styling.","ru":"Они генерируются автоматически: BBCode из Steam переводится в наш собственный стиль."},{"k":"b","lv":0,"en":"You can now see an announcement's thumbnail when sorting through news.","ru":"Теперь видна миниатюра объявления при просмотре новостей."},{"k":"b","lv":0,"en":"There is now a sorting dropdown, allowing you to decide how news should be sorted.","ru":"Появился выпадающий список сортировки новостей."},{"k":"b","lv":0,"en":"There is now a Copy Link, and Open in Browser buttons at the bottom left.","ru":"Слева внизу появились кнопки «Копировать ссылку» и «Открыть в браузере»."},{"k":"b","lv":0,"en":"URLs inside news/announcements in the News tab on the main menu are now clickable.","ru":"Ссылки в новостях/объявлениях на вкладке «Новости» главного меню теперь кликабельны."},{"k":"b","lv":1,"en":"Both Steam [url][/url] and raw https:// links are supported.","ru":"Поддерживаются и Steam-теги [url][/url], и обычные ссылки https://."},{"k":"b","lv":0,"en":"Social Media buttons are now present at the bottom right of the news menu.","ru":"Справа внизу меню новостей появились кнопки соцсетей."},{"k":"b","lv":0,"en":"Images will now be loaded into the news reader.","ru":"В читалке новостей теперь загружаются изображения."},{"k":"b","lv":0,"en":"The In-game/ESC Menu now utilizes the visual design of the Main Menu.","ru":"Внутриигровое меню (ESC) теперь в визуальном стиле главного меню."},{"k":"b","lv":0,"en":"Implemented a new unified ability framework for SCPs.","ru":"Внедрена новая единая система способностей для SCP."},{"k":"b","lv":0,"en":"Each playable SCP has received overhauled ability indicators.","ru":"Индикаторы способностей всех играбельных SCP полностью переработаны."},{"k":"b","lv":0,"en":"These indicators are placed at the bottom right of the screen, and display each of the SCP’s available abilities.","ru":"Индикаторы находятся в правом нижнем углу экрана и показывают все доступные способности SCP."},{"k":"b","lv":1,"en":"The keys associated with each ability are shown underneath their icons.","ru":"Клавиши каждой способности указаны под их иконками."},{"k":"b","lv":1,"en":"Ability cooldowns and duration are also visible when active.","ru":"Перезарядка и длительность способностей тоже видны, когда они активны."},{"k":"b","lv":0,"en":"Added a new hint system that utilizes new dialog boxes.","ru":"Добавлена новая система подсказок с новыми диалоговыми окнами."},{"k":"b","lv":1,"en":"Dialogs appear in the form of large or small dialogs.","ru":"Диалоги бывают большие и маленькие."},{"k":"b","lv":2,"en":"Large dialog boxes contain larger sets of information, and can be dismissed early by pressing B.","ru":"Большие окна содержат больше информации, их можно закрыть раньше клавишей B."},{"k":"b","lv":2,"en":"Small dialog boxes are briefer and relate to controls, and can be dismissed early by performing the action described.","ru":"Маленькие окна короче и касаются управления; они закрываются, если выполнить описанное действие."},{"k":"b","lv":1,"en":"Each role has its own defined set of hints designed to help teach newer players.","ru":"У каждой роли свой набор подсказок, призванный обучать новичков."},{"k":"b","lv":1,"en":"Players can also receive hints upon death, giving advice on what killed them.","ru":"После смерти игроки тоже могут получить подсказку — совет о том, что их убило."},{"k":"b","lv":0,"en":"Hints can be disabled or enabled in the settings.","ru":"Подсказки можно включить или выключить в настройках."},{"k":"b","lv":0,"en":"At the time of the beta release, there is a limited selection of hints. More hints will be added as time progresses.","ru":"На момент выхода беты подсказок немного. Со временем их станет больше."},{"k":"b","lv":0,"en":"Slightly increased the amount of misc locker and medical locker spawns.","ru":"Немного увеличено количество обычных и медицинских шкафчиков."},{"k":"b","lv":0,"en":"SCP Pedestals have been visually revamped.","ru":"Пьедесталы SCP визуально переработаны."},{"k":"b","lv":0,"en":"Using elevators that travel between different zones comes with a smoother transition between the two post-processing effects.","ru":"Переход между пост-эффектами зон при поездке на межзонных лифтах стал плавнее."},{"k":"b","lv":0,"en":"Overhauled the entire design and visual style of Surface Zone.","ru":"Полностью переработаны дизайн и визуальный стиль Поверхности."},{"k":"b","lv":1,"en":"Gate-A is designed as a civilian exit, containing two standard elevators that lead to Entrance Zone.","ru":"Ворота А — выход для гражданских: два стандартных лифта, ведущих в Офисную зону."},{"k":"b","lv":1,"en":"Gate-B is styled as an industrial and cargo area with a large akira elevator.","ru":"Ворота Б оформлены как промышленная и грузовая зона с большим лифтом-«акирой»."},{"k":"b","lv":1,"en":"The level design for Surface Zone has been entirely reworked: featuring new locations and pathways.","ru":"Левел-дизайн Поверхности полностью переделан: новые локации и пути."},{"k":"b","lv":1,"en":"Snow is now falling across all of Surface Zone.","ru":"На всей Поверхности теперь идёт снег."},{"k":"b","lv":1,"en":"The outside world should be far more visible and present than in the old iteration of Surface Zone.","ru":"Внешний мир стал намного заметнее и «присутствует» больше, чем в старой версии Поверхности."},{"k":"b","lv":2,"en":"Mountains fill the landscape, and icy roads lead to many civilians' hopeful escape.","ru":"Пейзаж заполнен горами, а обледенелые дороги ведут к долгожданному побегу многих гражданских."},{"k":"b","lv":0,"en":"Added a new CASSIE section to Surface Zone.","ru":"На Поверхность добавлена новая секция C.A.S.S.I.E."},{"k":"b","lv":1,"en":"This section is locked behind Tier-3 Administration doors. Once opened, they cannot be closed again.","ru":"Секция закрыта дверями Административного доступа 3-го уровня. После открытия их нельзя закрыть."},{"k":"b","lv":1,"en":"The Warhead Activation Console is located inside the room.","ru":"Внутри находится консоль активации боеголовки."},{"k":"b","lv":0,"en":"Added a new door type: the Garage Door, used in various buildings across Surface Zone.","ru":"Добавлен новый тип дверей — Гаражные ворота, используются в разных зданиях Поверхности."},{"k":"b","lv":1,"en":"This is a new door type which opens vertically.","ru":"Это новый тип двери, которая открывается вертикально."},{"k":"b","lv":1,"en":"Cannot be blown up or destroyed by SCP-096.","ru":"Её нельзя взорвать или сломать SCP-096."},{"k":"b","lv":1,"en":"SCP-096 can force them open much like gates.","ru":"SCP-096 может открыть их силой, как гермоворота."},{"k":"b","lv":0,"en":"Added new basic door models for buildings across Surface Zone.","ru":"Добавлены новые модели обычных дверей для зданий Поверхности."},{"k":"b","lv":0,"en":"Added the Surface Zone emergency backup generator.","ru":"Добавлен аварийный резервный генератор Поверхности."},{"k":"b","lv":1,"en":"This new generator is located in Gate-B, and only becomes unlocked after the Alpha Warhead detonates.","ru":"Новый генератор находится у Ворот Б и разблокируется только после детонации Альфа-боеголовки."},{"k":"b","lv":1,"en":"The generator takes 60 seconds to activate, and once activated will recontain SCP-079 and cause a militant wave to respawn in 30 seconds.","ru":"Активация занимает 60 секунд; после этого SCP-079 повторно содержится, а через 30 секунд появляется волна военных."},{"k":"b","lv":2,"en":"This militant wave is aligned with the team that activated it.","ru":"Эта волна принадлежит команде, которая активировала генератор."},{"k":"b","lv":1,"en":"The generator timer does not tick back up when it is disabled.","ru":"Таймер генератора не откатывается назад, если его отключить."},{"k":"b","lv":1,"en":"The generator will automatically start counting down 1:30 minutes after the warhead’s detonation.","ru":"Генератор автоматически начинает отсчёт через 1:30 после детонации боеголовки."},{"k":"b","lv":2,"en":"If the generator is activated via this method, the ensuing militant wave will be composed of NTF by default.","ru":"Если генератор активировался так, следующая волна по умолчанию будет из МОГ."},{"k":"b","lv":0,"en":"Added metal detectors as a gameplay map feature, currently present in Gate A.","ru":"Добавлены металлодетекторы как игровая механика карты — пока стоят у Ворот А."},{"k":"b","lv":1,"en":"Triggers an alarm sound when metallic items, or specific playable roles (which may carry certain detectable materials) pass through the sensors.","ru":"Звучит тревога, когда через сенсоры проходят металлические предметы или определённые роли (которые могут нести обнаруживаемые материалы)."},{"k":"b","lv":0,"en":"Introduced a new Surface Zone skybox, featuring satellite and star simulation.","ru":"Новый скайбокс Поверхности с симуляцией спутников и звёзд."},{"k":"b","lv":0,"en":"Doors on Surface Zone are no longer forced open during (nor after) the Alpha Warhead sequence.","ru":"Двери на Поверхности больше не открываются принудительно во время (и после) сценария Альфа-боеголовки."},{"k":"b","lv":1,"en":"Elevator doors are unaffected by this change and continue to behave as normal.","ru":"Двери лифтов это не затрагивает — они работают как обычно."},{"k":"b","lv":1,"en":"Because of this, SCP-2176 now works on Surface Zone during (and after) the Alpha Warhead sequence.","ru":"Благодаря этому SCP-2176 теперь работает на Поверхности во время (и после) сценария боеголовки."},{"k":"b","lv":0,"en":"Walls in Surface Zone have barbed wire, causing players various debuffs for walking over them:","ru":"На стенах Поверхности есть колючая проволока, которая накладывает дебаффы при ходьбе по ней:"},{"k":"b","lv":1,"en":"Decay 10% of their maximum HP per second.","ru":"Отнимает 10% максимального HP в секунду."},{"k":"b","lv":2,"en":"Functions akin to decontamination, and will go through HS/AHP first if the player has any.","ru":"Работает как деконтаминация: сначала снимает Hume-щит/AHP, если они есть."},{"k":"b","lv":1,"en":"Grants a 50% movement speed reduction.","ru":"Скорость передвижения снижена на 50%."},{"k":"b","lv":1,"en":"Grants a -100% accuracy modifier.","ru":"Модификатор точности −100%."},{"k":"b","lv":1,"en":"Disables sprinting and caps how high you can jump.","ru":"Отключает бег и ограничивает высоту прыжка."},{"k":"b","lv":1,"en":"Prevents the ability to reload.","ru":"Нельзя перезаряжаться."},{"k":"b","lv":0,"en":"Overhauled SCP-914's containment chamber.","ru":"Камера содержания SCP-914 полностью переработана."},{"k":"b","lv":1,"en":"The room is now a straight hallway and contains an elevator as an alternative exit.","ru":"Теперь это прямой коридор с лифтом в качестве альтернативного выхода."},{"k":"b","lv":1,"en":"SCP-914 is positioned downstairs with a guaranteed Scientist card spawn outside.","ru":"SCP-914 находится внизу, а снаружи гарантированно лежит карта учёного."},{"k":"b","lv":1,"en":"Now has a new map icon for SCP-079.","ru":"Получила новый значок на карте SCP-079."},{"k":"b","lv":0,"en":"Added a new elevator variant specific to SCP-914.","ru":"Добавлен новый вариант лифта специально для SCP-914."},{"k":"b","lv":1,"en":"This elevator appears the same as typical elevators, but automatically returns to the bottom (like the Servers elevator) and is slightly faster.","ru":"Выглядит как обычный лифт, но автоматически возвращается вниз (как лифт Серверной) и ездит чуть быстрее."},{"k":"b","lv":0,"en":"Made various changes to the PT-00 room:","ru":"Комната PT-00 получила ряд изменений:"},{"k":"b","lv":1,"en":"The security office section of PT-00 is now locked behind a Containment Tier 2 door.","ru":"Офис охраны в PT-00 теперь закрыт дверью Содержания 2-го уровня."},{"k":"b","lv":1,"en":"Within the security office, on the desk is a Research Supervisor spawn alongside a single SCP-500 instance.","ru":"В офисе охраны на столе лежит карта научного руководителя и один SCP-500."},{"k":"b","lv":2,"en":"There is a 50% chance for an additional Research Supervisor to spawn there.","ru":"С шансом 50% там появится ещё одна карта научного руководителя."},{"k":"b","lv":2,"en":"An SCP item pedestal can no longer spawn in the room.","ru":"Пьедестал с SCP-предметом больше не может появиться в комнате."},{"k":"b","lv":2,"en":"A new office desk is placed in the room where the Zone Manager and COM-15 spawns are relocated to.","ru":"В комнате поставлен новый офисный стол — туда перенесены спавны карты менеджера зоны и COM-15."},{"k":"b","lv":0,"en":"Four of the existing LCZ layouts have been replaced with new, slightly larger ones.","ru":"Четыре существующие раскладки Лёгкой зоны заменены новыми, чуть более крупными."},{"k":"b","lv":0,"en":"A new VT-00 variant now spawns, labeled as \"VT-01\".","ru":"Появился новый вариант VT-00 — «VT-01»."},{"k":"b","lv":1,"en":"The room appears as the old VT-00 variant with both sides being glass with plants behind them.","ru":"Комната выглядит как старый VT-00, но обе стороны — стекло с растениями за ним."},{"k":"b","lv":1,"en":"VT-01 also has a possible COM-15 spawn on top of the standard VT-00 loot.","ru":"В VT-01 помимо обычного лута VT-00 может появиться COM-15."},{"k":"b","lv":1,"en":"No lockers (outside of Pedestals) can spawn in VT-01.","ru":"В VT-01 не появляются шкафчики (кроме пьедесталов)."},{"k":"b","lv":0,"en":"To replace the missing endroom (since SCP-914 is now a straight hallway), Elevator System C has been added.","ru":"Чтобы заменить пропавшую тупиковую комнату (SCP-914 теперь прямой коридор), добавлена Лифтовая система C."},{"k":"b","lv":1,"en":"Elevator-C will be a copy of the existing elevators with the \"-C\" label.","ru":"Лифт C — копия существующих лифтов с пометкой «-C»."},{"k":"b","lv":0,"en":"Due to this, all HCZ layouts have been slightly modified with a new endroom spawn each.","ru":"Из-за этого все раскладки Тяжёлой зоны немного изменены — в каждой появилась новая тупиковая комната."},{"k":"b","lv":0,"en":"The LCZ Corner and T-Intersection rooms previously present in PEARS 5 are implemented into the live game to enhance loot distribution and variety within LCZ.","ru":"Угловые комнаты и Т-образные перекрёстки Лёгкой зоны из PEARS 5 добавлены в основную игру для лучшего и разнообразного распределения лута."},{"k":"b","lv":1,"en":"Normal Corner and T-Intersections still spawn.","ru":"Обычные углы и Т-перекрёстки тоже по-прежнему появляются."},{"k":"c","lv":0,"en":"A lot of these changes are inspired from PEARS-5: a test that was hosted earlier in the year that overhauled the early game. While we are still interested in potentially pursuing the early game overhaul in the future, we decided to include some of the smaller, well-received changes in Megapatch III. We hope you enjoy!","ru":"Многое здесь вдохновлено PEARS-5 — тестом в начале года, который перерабатывал раннюю игру. Мы всё ещё рассматриваем полную переработку раннего этапа в будущем, но решили включить в Megapatch III часть небольших изменений, которые понравились игрокам. Надеемся, вам понравится!"},{"k":"b","lv":0,"en":"Completely overhauled the Entrance Zone sides of Gate-A and Gate-B.","ru":"Стороны Ворот А и Б в Офисной зоне полностью переработаны."},{"k":"b","lv":1,"en":"The rooms now have multiple connections to other rooms.","ru":"Комнаты теперь соединены с несколькими другими комнатами."},{"k":"b","lv":1,"en":"Gate-B contains a large, industrial akira elevator.","ru":"У Ворот Б — большой промышленный лифт-«акира»."},{"k":"b","lv":1,"en":"Gate-A contains two standard civilian elevators.","ru":"У Ворот А — два стандартных гражданских лифта."},{"k":"b","lv":1,"en":"At the time of the beta release, the two rooms are currently in graybox form.","ru":"На момент выхода беты обе комнаты в виде «грейбокса» (черновой геометрии)."},{"k":"b","lv":0,"en":"Introduced five new layouts for Entrance Zone to accommodate for the new gates.","ru":"Добавлено пять новых раскладок Офисной зоны под новые ворота."},{"k":"b","lv":1,"en":"For the time being, these layouts exclude all other endrooms aside from the gates due to feasibility issues.","ru":"Пока что в этих раскладках нет других тупиковых комнат, кроме ворот, — по техническим причинам."},{"k":"b","lv":2,"en":"They will be brought back in the future.","ru":"В будущем их вернут."},{"k":"b","lv":0,"en":"Breakable glasses in Entrance Zone now have different default visuals.","ru":"Бьющиеся стёкла в Офисной зоне выглядят по-новому."},{"k":"b","lv":1,"en":"Their health has increased from 20 to 100.","ru":"Их прочность увеличена с 20 до 100."},{"k":"b","lv":0,"en":"SCP-079 Generators have been visually revamped.","ru":"Генераторы SCP-079 визуально переработаны."},{"k":"b","lv":0,"en":"Added six new variants of the Deep Corner room to Heavy Containment Zone.","ru":"В Тяжёлую зону добавлено шесть новых вариантов комнаты «Глубокий угол»."},{"k":"b","lv":1,"en":"Each variant is not fully guaranteed to spawn each round.","ru":"Каждый вариант не гарантированно появляется в раунде."},{"k":"b","lv":0,"en":"Made various adjustments and fixes to the Ramp Intersection room:","ru":"Ряд правок и исправлений в комнате «Перекрёсток с рампой»:"},{"k":"b","lv":1,"en":"Added a tarp and fence to the left stairwell to remove a sightline.","ru":"На левую лестницу добавлены брезент и забор, чтобы убрать простреливаемую линию."},{"k":"b","lv":1,"en":"Adjusted position of wooden planks.","ru":"Изменено положение деревянных досок."},{"k":"b","lv":1,"en":"Adjusted pipes on the wall to block a troublesome sightline.","ru":"Трубы на стене передвинуты, чтобы закрыть неудобную линию обзора."},{"k":"b","lv":1,"en":"Fixed issue where locked door would clip into window when opened by ghostlight.","ru":"Исправлено: запертая дверь проходила сквозь окно при открытии «призрачным светом»."},{"k":"b","lv":1,"en":"Fixed issue where SCP-079's camera would clip into the wall.","ru":"Исправлено: камера SCP-079 проходила сквозь стену."},{"k":"b","lv":1,"en":"Fixed pixel walk next to stairs with mesh fence.","ru":"Исправлен «пиксельный» проход возле лестницы с сетчатым забором."},{"k":"b","lv":0,"en":"Adjusted lighting and props in the following rooms:","ru":"Освещение и декорации изменены в комнатах:"},{"k":"b","lv":1,"en":"Tesla Room.","ru":"Комната с Теслой."},{"k":"b","lv":1,"en":"SCP-079's Containment Chamber.","ru":"Камера содержания SCP-079."},{"k":"b","lv":1,"en":"SCP-127's Containment Chamber.","ru":"Камера содержания SCP-127."},{"k":"b","lv":1,"en":"Alpha Warhead Silo.","ru":"Шахта Альфа-боеголовки."},{"k":"b","lv":0,"en":"Increased SCP-079 armory's glass health from 5 to 25 (From 1 hit to roughly ~2 hits).","ru":"Прочность стекла оружейной SCP-079 увеличена с 5 до 25 (с 1 удара до ~2)."},{"k":"b","lv":1,"en":"This is the armored/reinforced window next to the firearms, not the button's glass.","ru":"Речь о бронированном окне рядом с оружием, а не о стекле над кнопкой."},{"k":"b","lv":0,"en":"Removed the fence clutter from spawning in SCP-079's room.","ru":"Убран заборный «мусор» в комнате SCP-079."},{"k":"b","lv":1,"en":"This was done to prevent collisions with the Generator that sometimes spawns in it.","ru":"Это сделано, чтобы он не пересекался с генератором, который иногда там появляется."},{"k":"b","lv":0,"en":"The Guard keycard spawn in SCP-049’s sublevel is replaced with a Research Supervisor spawn.","ru":"Спавн карты охраны на подуровне SCP-049 заменён на карту научного руководителя."},{"k":"b","lv":0,"en":"HCZ's Warhead panel has been visually revamped.","ru":"Панель боеголовки в Тяжёлой зоне визуально переработана."},{"k":"b","lv":0,"en":"Phones spawn in a lot of locations, including all containment chambers and rooms with special points of interest (warhead, labs, etc.).","ru":"Телефоны есть во многих местах, включая все камеры содержания и комнаты с важными точками (боеголовка, лаборатории и т. д.)."},{"k":"b","lv":0,"en":"All roles can make calls by interacting with a phone. When that happens, all phones in the facility will ring at once.","ru":"Любая роль может позвонить, взаимодействуя с телефоном. Тогда все телефоны комплекса зазвонят одновременно."},{"k":"b","lv":0,"en":"When someone answers the phone, they can talk to each other by simply transmitting on proximity voice. SCPs that don't have proximity voice chat can still listen, but can't transmit.","ru":"Когда кто-то берёт трубку, собеседники могут говорить друг с другом через обычный голосовой чат рядом. SCP без голосового чата могут слушать, но не говорить."},{"k":"b","lv":0,"en":"When someone misses the phone, the phone stops ringing, but they can still join the call by interacting with the phone again.","ru":"Если кто-то пропустил звонок, телефон перестаёт звонить, но к разговору можно подключиться, снова взаимодействовав с телефоном."},{"k":"b","lv":0,"en":"As with radios and intercom, only voice data is transmitted. Environmental sounds are not recorded.","ru":"Как и в рации и интеркоме, передаётся только голос. Звуки окружения не записываются."},{"k":"b","lv":0,"en":"When the last person in proximity to the phone interacts with it or walks away, the phone will automatically disconnect.","ru":"Когда последний человек рядом с телефоном взаимодействует с ним или уходит, телефон автоматически отключается."},{"k":"b","lv":0,"en":"The display on the model lists all connected phones.","ru":"Дисплей на модели показывает все подключённые телефоны."},{"k":"b","lv":0,"en":"SCP-939 interactions:","ru":"Взаимодействие с SCP-939:"},{"k":"b","lv":1,"en":"Recorded player voices can be transmitted through the phone.","ru":"Записанные голоса игроков можно передавать через телефон."},{"k":"b","lv":1,"en":"This does not affect other mimicry, such as gunshots or footsteps.","ru":"Другую мимикрию (выстрелы, шаги) это не затрагивает."},{"k":"b","lv":0,"en":"SCP-079 interactions:","ru":"Взаимодействие с SCP-079:"},{"k":"b","lv":1,"en":"If the camera is in range of the phone, voice will automatically be picked up by phones without needing to interact. The same applies to hearing players.","ru":"Если камера рядом с телефоном, голос автоматически передаётся без взаимодействия. То же касается прослушивания игроков."},{"k":"b","lv":1,"en":"If the camera is farther away, interacting with the phone will allow SCP-079 to transmit and hear voice regardless of distance.","ru":"Если камера дальше, взаимодействие с телефоном позволяет SCP-079 говорить и слушать на любом расстоянии."},{"k":"b","lv":1,"en":"Otherwise, pressing the icon is the same as pressing the interact button, like a regular player.","ru":"В остальном нажатие на значок работает как обычное взаимодействие игрока."},{"k":"b","lv":0,"en":"IMPORTANT DISCLAIMER: We have moved the majority of our code from the Assembly-CSharp.dll. Read below for more info.","ru":"ВАЖНО: основная часть кода перенесена из Assembly-CSharp.dll. Подробнее ниже."},{"k":"b","lv":1,"en":"This means that you will need to update your .csproj files to point towards the new files based on what you are accessing.","ru":"Это значит, что нужно обновить .csproj-файлы, указав новые сборки в зависимости от того, что вы используете."},{"k":"b","lv":0,"en":"Moved the game's code into it's own separate assembly: Northwood.SCPSL.","ru":"Код игры вынесен в отдельную сборку: Northwood.SCPSL."},{"k":"b","lv":0,"en":"Moved Version, HolidayType, and BuildData to its own separate assembly: Northwood.Versioning.","ru":"Version, HolidayType и BuildData вынесены в отдельную сборку: Northwood.Versioning."},{"k":"b","lv":0,"en":"Various libraries, frameworks, and tools have been given their own assemblies:","ru":"Ряд библиотек, фреймворков и инструментов получили собственные сборки:"},{"k":"b","lv":1,"en":"HeadlessBuilder.","ru":"HeadlessBuilder."},{"k":"b","lv":1,"en":"SteamUtils.","ru":"SteamUtils."},{"k":"b","lv":1,"en":"MEC.","ru":"MEC."},{"k":"b","lv":1,"en":"LiteNetLib4Mirror.","ru":"LiteNetLib4Mirror."},{"k":"b","lv":1,"en":"DiscordGameSDK.","ru":"DiscordGameSDK."},{"k":"b","lv":1,"en":"StandardAssets.","ru":"StandardAssets."},{"k":"b","lv":1,"en":"Utf8Json.","ru":"Utf8Json."},{"k":"b","lv":0,"en":"Upgraded Unity engine version to 6000.4.11f1.","ru":"Движок Unity обновлён до версии 6000.4.11f1."},{"k":"b","lv":0,"en":"Upgraded NorthwoodLib to the latest build.","ru":"NorthwoodLib обновлена до последней сборки."},{"k":"b","lv":0,"en":"Added experimental-optimizations startup argument, which enables various Mono JIT optimizations.","ru":"Добавлен аргумент запуска experimental-optimizations, включающий ряд JIT-оптимизаций Mono."},{"k":"b","lv":0,"en":"Updated MEC to 3.17.0.","ru":"MEC обновлён до 3.17.0."},{"k":"b","lv":0,"en":"Improved load times when running the game from an NVMe SSD drive by using the DirectStorage API.","ru":"Ускорена загрузка с NVMe SSD за счёт DirectStorage API."},{"k":"b","lv":0,"en":"Implemented a secondary motion framework that supports physics-based movement of character elements such as tails, hair, belts, pouches, carabiners.","ru":"Внедрена система вторичной анимации, поддерживающая физику элементов персонажа: хвостов, волос, ремней, подсумков, карабинов."},{"k":"b","lv":0,"en":"The character model animator now supports additional non-humanoid animated bones.","ru":"Аниматор моделей персонажей теперь поддерживает дополнительные негуманоидные кости."},{"k":"b","lv":1,"en":"This allows our previously implemented animations (such as SCP-939 spine spikes) to apply their motion correctly.","ru":"Благодаря этому ранее сделанные анимации (например, шипы на спине SCP-939) двигаются корректно."},{"k":"b","lv":0,"en":"All human models now share the same Animator avatar definition to avoid cross-rig retargeting.","ru":"Все человеческие модели теперь используют одно определение аватара Animator, чтобы избежать ретаргетинга между ригами."},{"k":"b","lv":0,"en":"Refactored AnimatorLayerManager to store layer references in a shared scriptable object, which optimizes instantiation time.","ru":"AnimatorLayerManager переработан: ссылки на слои хранятся в общем ScriptableObject, что ускоряет создание объектов."},{"k":"b","lv":0,"en":"Globally disabled raycasts being able to hit trigger colliders.","ru":"Глобально отключено попадание рейкастов в триггер-коллайдеры."},{"k":"b","lv":0,"en":"Added MultipleDoorController.","ru":"Добавлен MultipleDoorController."},{"k":"b","lv":1,"en":"These act as one interactable through gameplay, meaning that interacting with it will cause both doors to open, close, lock, unlock, explode and repair.","ru":"Работает как один интерактивный объект: взаимодействие открывает, закрывает, блокирует, разблокирует, взрывает и чинит обе двери сразу."},{"k":"b","lv":0,"en":"Optimized Dedicated Server by destroying or ignoring methods which were not necessary to run based on community suggestions.","ru":"Выделенный сервер оптимизирован: по предложениям сообщества удалены или пропускаются ненужные методы."},{"k":"b","lv":0,"en":"Culling will now always affect objects beyond 150m from the player regardless of the fog setting.","ru":"Отсечение (culling) теперь всегда действует на объекты дальше 150 м от игрока, независимо от настройки тумана."},{"k":"b","lv":1,"en":"It'll still respect the fog up to that point though.","ru":"До этой дистанции туман по-прежнему учитывается."},{"k":"b","lv":0,"en":"Reduced memory allocations caused by the hotkey system.","ru":"Уменьшено выделение памяти системой горячих клавиш."},{"k":"b","lv":0,"en":"Added frameworks for self-serializing messages, meaning we can create serializers and deserializers directly within the struct, instead of needing an extension method from a static class.","ru":"Добавлены фреймворки для самосериализующихся сообщений — сериализаторы и десериализаторы можно писать прямо внутри структуры, без extension-метода в статическом классе."},{"k":"b","lv":0,"en":"Implemented new tech which allows us to rotate reflection probe cubemaps.","ru":"Новая технология позволяет вращать кубмапы reflection probe."},{"k":"b","lv":0,"en":"Updated the hair shader to support softer materials.","ru":"Шейдер волос обновлён для поддержки более мягких материалов."},{"k":"b","lv":0,"en":"Audio effects now use mixer snapshots instead of controlling individual parameters.","ru":"Аудиоэффекты теперь используют снапшоты микшера вместо управления отдельными параметрами."},{"k":"b","lv":1,"en":"This allows for more complex audio processing caused by status effects.","ru":"Это позволяет делать более сложную обработку звука от статус-эффектов."},{"k":"b","lv":0,"en":"Refactored ServerRoles.NamedColor array into a separate scriptable object and linked it using FastResources.","ru":"Массив ServerRoles.NamedColor вынесен в отдельный ScriptableObject и подключён через FastResources."},{"k":"b","lv":1,"en":"This reduces instantiation time of the player prefab and makes the color easier to access.","ru":"Это сокращает время создания префаба игрока и упрощает доступ к цвету."},{"k":"b","lv":0,"en":"Registered various networked objects to the list of objects spawnable by the server.","ru":"Ряд сетевых объектов зарегистрирован в списке объектов, которые может спавнить сервер."},{"k":"b","lv":1,"en":"Barbed Wire.","ru":"Колючая проволока."},{"k":"b","lv":1,"en":"Tesla Gate.","ru":"Тесла-ворота."},{"k":"b","lv":1,"en":"Landline Phones.","ru":"Стационарные телефоны."},{"k":"b","lv":1,"en":"Garage Door.","ru":"Гаражные ворота."},{"k":"b","lv":1,"en":"Other miscellaneous doors which were not available until now.","ru":"Прочие двери, которые раньше были недоступны."},{"k":"b","lv":0,"en":"Implemented KillAssistTracker abstract subroutine. Tracks player deaths and invokes a method whenever a kill counts as \"assisted\".","ru":"Добавлена абстрактная подпрограмма KillAssistTracker. Отслеживает смерти игроков и вызывает метод, когда убийство засчитывается как «ассист»."},{"k":"b","lv":1,"en":"Most of its logic is stripped directly from SCP-939's Mimicry Recorder, simply abstracted for general use.","ru":"Большая часть логики взята из Записывателя мимикрии SCP-939 и просто абстрагирована для общего использования."},{"k":"b","lv":1,"en":"SCP-939's Mimicry recorder was moved to utilize this new module.","ru":"Записыватель мимикрии SCP-939 переведён на этот новый модуль."},{"k":"b","lv":0,"en":"StandardSubroutine<T>'s T must now be a ISubroutinedRole. This optimizes the GetSubroutine<TSubroutine> call, and makes more sense moving forward.","ru":"T в StandardSubroutine<T> теперь обязан быть ISubroutinedRole. Это оптимизирует вызов GetSubroutine<TSubroutine> и логичнее в перспективе."},{"k":"b","lv":1,"en":"This change extends to ALL generic classes that derive from this, such as KeySubroutine<T>, ScpAttackAbilityBase<T>, and a few others.","ru":"Изменение касается ВСЕХ наследующих generic-классов: KeySubroutine<T>, ScpAttackAbilityBase<T> и ряда других."},{"k":"b","lv":0,"en":"Implemented SmoothBoolean utility script, which is used to change a boolean value over time. You are able to define how long it takes to get to the target boolean value.","ru":"Добавлен утилитный скрипт SmoothBoolean — плавно меняет булево значение со временем. Можно задать, сколько длится переход к целевому значению."},{"k":"b","lv":1,"en":"You are able to define the transition duration separately per true/false state.","ru":"Длительность перехода можно задать отдельно для состояний true/false."},{"k":"b","lv":0,"en":"Added KeySyncSubroutine<TRole>, it inherits the KeySubroutine<TRole> class and expands it by automatically synchronizing the IsKeyHeld property value.","ru":"Добавлен KeySyncSubroutine<TRole> — наследует KeySubroutine<TRole> и автоматически синхронизирует свойство IsKeyHeld."},{"k":"b","lv":0,"en":"PlayerRoleManager now keeps track of the previous role and team. This is done once upon the role being assigned to the player.","ru":"PlayerRoleManager теперь хранит предыдущую роль и команду. Это делается один раз при назначении роли."},{"k":"b","lv":1,"en":"These properties can be null, in case of no previous roles existing.","ru":"Эти свойства могут быть null, если предыдущих ролей не было."},{"k":"b","lv":1,"en":"WaveSpawner now uses this system rather than keeping track of the roles itself.","ru":"WaveSpawner теперь использует эту систему вместо собственного отслеживания ролей."},{"k":"b","lv":0,"en":"Removed ItemTierFlags in favor of new ItemFlags & ItemRarity.","ru":"ItemTierFlags удалены в пользу новых ItemFlags и ItemRarity."},{"k":"b","lv":1,"en":"ItemFlags is used to bundle items together across different categories, items can have any (or no) flags.","ru":"ItemFlags объединяют предметы в категории; у предмета может быть любое число флагов (или ни одного)."},{"k":"b","lv":2,"en":"Some examples of flags: Lethal, Utility, Consumable, etc.","ru":"Примеры флагов: Lethal, Utility, Consumable и т. д."},{"k":"b","lv":1,"en":"ItemRarity is used to classify how rare an item is.","ru":"ItemRarity задаёт редкость предмета."},{"k":"b","lv":2,"en":"Common: The default rarity for all items.","ru":"Common: стандартная редкость для всех предметов."},{"k":"b","lv":2,"en":"Rare: This is for items which spawn in limited amounts across the facility, or in low amounts through spawn waves.","ru":"Rare: предметы, которые появляются в ограниченном количестве по комплексу или в малом количестве с волнами."},{"k":"b","lv":2,"en":"Unique: This is for items which only spawn once in the Facility, or obtained through very difficult means.","ru":"Unique: предметы, которые появляются в комплексе лишь один раз или добываются очень сложно."},{"k":"b","lv":1,"en":"Both of these are now shown when hovering over items in RemoteAdmin.","ru":"Оба параметра теперь видны при наведении на предметы в RemoteAdmin."},{"k":"b","lv":2,"en":"Rare items are colored purple in RA, Unique items are colored red.","ru":"Редкие предметы в RA фиолетовые, уникальные — красные."},{"k":"b","lv":0,"en":"Added MouseLock effect. It locks the mouse movement, but still allows players to move around.","ru":"Добавлен эффект MouseLock — блокирует движение мыши, но позволяет ходить."},{"k":"b","lv":0,"en":"ItemType is now under the InventorySystem.Items namespace.","ru":"ItemType теперь в пространстве имён InventorySystem.Items."},{"k":"b","lv":0,"en":"Renamed IHudScp to IHudRole as to support non-SCP roles utilizing custom HUDs.","ru":"IHudScp переименован в IHudRole для поддержки собственных HUD у не-SCP ролей."},{"k":"b","lv":0,"en":"Refactored ScpHudBase as to support non-SCP roles utilizing custom HUDs.","ru":"ScpHudBase переработан для поддержки собственных HUD у не-SCP ролей."},{"k":"b","lv":1,"en":"HudElementBase is the base of all HUD elements (The HUDs themselves included).","ru":"HudElementBase — база всех элементов HUD (включая сами HUD)."},{"k":"b","lv":1,"en":"RoleHudElementBase<TRole> is a variant of the above, allowing to store a reference cast to TRole.","ru":"RoleHudElementBase<TRole> — вариант выше, хранящий ссылку, приведённую к TRole."},{"k":"b","lv":1,"en":"ChildHudElementBase<THud, TRole> is a variant of the above, allowing to directly reference the \"Main HUD\" that owns this element.","ru":"ChildHudElementBase<THud, TRole> — вариант выше, позволяющий напрямую ссылаться на «главный HUD», владеющий элементом."},{"k":"b","lv":1,"en":"MainHudBase<TRole> allows for owning elements, toggling them off when HUD is disabled, and initializing them in the correct order.","ru":"MainHudBase<TRole> умеет владеть элементами, отключать их вместе с HUD и инициализировать в правильном порядке."},{"k":"b","lv":1,"en":"ScpHudBase still exists, and inherits MainHudBase<TRole>. Its exclusive benefit is handling the target counter that all SCPs have.","ru":"ScpHudBase остался и наследует MainHudBase<TRole>. Его уникальная функция — счётчик целей, общий для всех SCP."},{"k":"b","lv":0,"en":"SimpleInspectorModule._isInspecting was removed in favor of directly using SimpleInspectorModule.DisplayInspecting.","ru":"SimpleInspectorModule._isInspecting удалён — используйте напрямую SimpleInspectorModule.DisplayInspecting."},{"k":"b","lv":0,"en":"Added StatBase.CalculateNormalizedValue method, it calculates the normalized value based on the specified value.","ru":"Добавлен метод StatBase.CalculateNormalizedValue — вычисляет нормализованное значение по заданному."},{"k":"b","lv":0,"en":"Added StatBase.CalculateValue method, it calculates the value of the stat at the specified normalized value.","ru":"Добавлен метод StatBase.CalculateValue — вычисляет значение характеристики по нормализованному."},{"k":"b","lv":0,"en":"Added Inventory.ServerDropItem so you can drop a player's inventory as the server.","ru":"Добавлен Inventory.ServerDropItem — сервер может выбросить предмет из инвентаря игрока."},{"k":"b","lv":0,"en":"The following methods have been made public as to improve dummy controlling support:","ru":"Следующие методы стали публичными для лучшей поддержки управления дамми:"},{"k":"b","lv":1,"en":"DummyKeyEmulator.RemoveEntry.","ru":"DummyKeyEmulator.RemoveEntry."},{"k":"b","lv":1,"en":"DummyKeyEmulator.AddEntry.","ru":"DummyKeyEmulator.AddEntry."},{"k":"b","lv":1,"en":"SubroutineBase.DummyEmulator.","ru":"SubroutineBase.DummyEmulator."},{"k":"b","lv":1,"en":"AutoSyncItem.DummyEmulator.","ru":"AutoSyncItem.DummyEmulator."},{"k":"b","lv":1,"en":"AutoSyncItem.IsEmulatedDummy.","ru":"AutoSyncItem.IsEmulatedDummy."},{"k":"b","lv":1,"en":"ItemBase.IsDummy.","ru":"ItemBase.IsDummy."},{"k":"b","lv":1,"en":"InteractionCoordinator.ClientInteract.","ru":"InteractionCoordinator.ClientInteract."},{"k":"b","lv":1,"en":"InteractionCoordinator.GetSafeRule.","ru":"InteractionCoordinator.GetSafeRule."},{"k":"b","lv":0,"en":"Added ability to remove the collider in SCP-096 Chamber by removing the door.","ru":"Коллайдер в камере SCP-096 теперь можно убрать, удалив дверь."},{"k":"b","lv":0,"en":"Moved registration of some networked objects away from the NetworkManager prefab to a new dynamic loading system integrated within FastResources.","ru":"Регистрация части сетевых объектов перенесена из префаба NetworkManager в новую систему динамической загрузки внутри FastResources."},{"k":"b","lv":1,"en":"This shouldn't really suppose a change, but we are mentioning it for those with hack-y solutions.","ru":"По сути ничего не должно поменяться, но упоминаем для тех, у кого «костыльные» решения."},{"k":"b","lv":0,"en":"Removed background from Waiting For Players screen.","ru":"Убран фон с экрана ожидания игроков."},{"k":"b","lv":0,"en":"Added limit of 100 characters when writing Keycard's Custom Label, Custom Item Name, Custom NameTag.","ru":"Добавлен лимит в 100 символов для Custom Label карт-ключа, Custom Item Name и Custom NameTag."},{"k":"b","lv":1,"en":"This was done as large labels could cause server softlocks and/or crashes.","ru":"Слишком длинные надписи могли вешать или крашить сервер."},{"k":"b","lv":0,"en":"\"Command execution failed!\" messages are now also logged through Unity's Debug.LogError.","ru":"Сообщения «Command execution failed!» теперь также пишутся через Debug.LogError в Unity."},{"k":"b","lv":0,"en":"Added ICrossCompatibleModel interface. This allows us to mark models which support compatibility when not used by the appropriate role.","ru":"Добавлен интерфейс ICrossCompatibleModel — помечает модели, поддерживающие совместимость при использовании «чужой» ролью."},{"k":"b","lv":1,"en":"This is specifically used by SCP-953 so models which rely on specific subroutines such as SCP-049-2's can be used safely by her.","ru":"Используется именно SCP-953, чтобы модели, зависящие от особых подпрограмм (например, SCP-049-2), безопасно ею использовались."},{"k":"b","lv":0,"en":"Added BlockedInteraction.ItemConsumption restriction.","ru":"Добавлено ограничение BlockedInteraction.ItemConsumption."},{"k":"b","lv":1,"en":"This allows using items, but not consuming them nor using their effect. For guns, this means being able to shoot them, but not deal damage nor consume ammo.","ru":"Позволяет использовать предметы, но не расходовать их и не получать эффект. Для оружия — можно стрелять, но без урона и без расхода патронов."},{"k":"b","lv":2,"en":"Some firearms don't fully support the \"not consuming ammo\" part, we may expand it to all in the future, but we are prioritizing SCP-953's mechanics first.","ru":"Некоторое оружие пока не полностью поддерживает «без расхода патронов» — возможно, позже расширим на всё, но приоритет сейчас — механики SCP-953."},{"k":"b","lv":1,"en":"This doesn't work with all items, as it is currently an exclusive SCP-953 mechanic, it currently only supports the items that SCP-953 is able to grab.","ru":"Работает не со всеми предметами: сейчас это эксклюзивная механика SCP-953 и поддерживает только предметы, которые она может хватать."},{"k":"b","lv":0,"en":"Added StandardSubroutine.ServerSendRpcToView. Simplifies sending the ServerSendRpc to Owner and any current spectators.","ru":"Добавлен StandardSubroutine.ServerSendRpcToView — упрощает отправку ServerSendRpc владельцу и текущим наблюдателям."},{"k":"b","lv":0,"en":"The Round's timer is now synchronized from the server to clients.","ru":"Таймер раунда теперь синхронизируется с сервера на клиентов."},{"k":"b","lv":1,"en":"This is a one-time transaction using a networked timestamp, meaning that it won't affect performance.","ru":"Это разовая передача через сетевую метку времени — на производительность не влияет."},{"k":"b","lv":0,"en":"The following ScpAttackAbilityBase's properties have been made public:","ru":"Следующие свойства ScpAttackAbilityBase стали публичными:"},{"k":"b","lv":1,"en":"AttackDelay.","ru":"AttackDelay."},{"k":"b","lv":1,"en":"BaseCooldown.","ru":"BaseCooldown."},{"k":"b","lv":1,"en":"SelfRepeating.","ru":"SelfRepeating."},{"k":"b","lv":1,"en":"DetectionRadius.","ru":"DetectionRadius."},{"k":"b","lv":1,"en":"DetectionOffset.","ru":"DetectionOffset."},{"k":"b","lv":0,"en":"AnimatorLayerManager now contains shortcuts for moving the weight using MoveTowards.","ru":"В AnimatorLayerManager добавлены шорткаты для изменения веса через MoveTowards."},{"k":"b","lv":0,"en":"Implemented TryGetFirst utility method for FastResources, or objects that only exist as singletons.","ru":"Добавлен утилитный метод TryGetFirst для FastResources и объектов-синглтонов."},{"k":"b","lv":0,"en":"Added IsExcludedFromGameplay to ReferenceHub, which allows for fast checking if the hub belongs to an unauthenticated connection or dedicated server.","ru":"В ReferenceHub добавлен IsExcludedFromGameplay — быстрая проверка, принадлежит ли хаб неавторизованному подключению или выделенному серверу."},{"k":"b","lv":0,"en":"Added utility methods for repetitive setting goals and weights of Inverse Kinematics.","ru":"Добавлены утилиты для повторяющейся установки целей и весов инверсной кинематики."},{"k":"b","lv":0,"en":"ServerDropEverything now contains an optional parameter which allows to populate a list with all pickups that have been created as a result of this method.","ru":"ServerDropEverything получил необязательный параметр, позволяющий заполнить список всеми созданными этим методом пикапами."},{"k":"b","lv":0,"en":"Abstracted damage animation effect that was previously used by SCP-939 (twitching animation and grunts of being shot at).","ru":"Абстрагирован эффект анимации получения урона, ранее использовавшийся SCP-939 (подёргивание и стоны при попадании)."},{"k":"b","lv":1,"en":"It is now an animator subcontroller so it can be reused by any animated character model.","ru":"Теперь это подконтроллер аниматора, который может использовать любая анимированная модель."},{"k":"b","lv":0,"en":"Added ModelCurveProviderStateMachine StateMachine component, which allows animator states to supply scripts with additional curves.","ru":"Добавлен компонент ModelCurveProviderStateMachine — позволяет состояниям аниматора передавать скриптам дополнительные кривые."},{"k":"b","lv":0,"en":"Added a RoleAssignPriority to spawnpoint handlers, which allows to dictate in which order roles are assigned to players on round start.","ru":"В обработчики точек появления добавлен RoleAssignPriority — задаёт порядок назначения ролей игрокам в начале раунда."},{"k":"b","lv":0,"en":"Abstracted StatFlasher to support flashing of any PlayerStats sliders.","ru":"StatFlasher абстрагирован для поддержки мигания любых слайдеров PlayerStats."},{"k":"b","lv":0,"en":"Subroutines now feature a UniqueHash which is a stable unique identifier of a subroutine within that role, used to access the subroutine across prefabs.","ru":"У подпрограмм появился UniqueHash — стабильный уникальный идентификатор подпрограммы внутри роли для доступа к ней между префабами."},{"k":"b","lv":0,"en":"Removed Scp079CurrentCameraSync.CurrentCamera in order to improve support for custom maps.","ru":"Удалён Scp079CurrentCameraSync.CurrentCamera для лучшей поддержки кастомных карт."},{"k":"b","lv":1,"en":"This means that all occurrences of this have been replaced with TryGetCurrentCamera, which provides a safer option.","ru":"Все его использования заменены на более безопасный TryGetCurrentCamera."},{"k":"b","lv":0,"en":"Introduced a new struct, PCMData, which is a wrapper for a recyclable sample array and its target length.","ru":"Добавлена новая структура PCMData — обёртка над переиспользуемым массивом сэмплов и его целевой длиной."},{"k":"b","lv":1,"en":"All buffers and audio modules use it to pass samples around.","ru":"Все буферы и аудиомодули передают сэмплы через неё."},{"k":"b","lv":0,"en":"Added PlayerStats.KillPlayer method.","ru":"Добавлен метод PlayerStats.KillPlayer."},{"k":"b","lv":1,"en":"Previously the entire killing logic was inside PlayerStats.DealDamage, this replaces that, and cleanly separates the logic.","ru":"Раньше вся логика убийства была внутри PlayerStats.DealDamage — теперь она аккуратно разделена."},{"k":"b","lv":0,"en":"Added various verification checks to prevent interacting with lockers through walls.","ru":"Добавлены проверки, не позволяющие взаимодействовать со шкафчиками сквозь стены."},{"k":"b","lv":0,"en":"Added NetworkServer.active check to OnEnable and OnEffectUpdate in Resurrected status effect.","ru":"В OnEnable и OnEffectUpdate статус-эффекта Resurrected добавлена проверка NetworkServer.active."},{"k":"b","lv":1,"en":"This allows plugins to patch those methods properly without the client overriding the visuals.","ru":"Это позволяет плагинам корректно патчить эти методы, не перезаписывая визуал клиентом."},{"k":"b","lv":0,"en":"Refactored LCZ decontamination to be more server-side, with the server now sending client announcement messages as well as the elapsed time that has passed.","ru":"Деконтаминация Лёгкой зоны переработана и стала более серверной: сервер сам отправляет клиентам объявления и прошедшее время."},{"k":"b","lv":0,"en":"LCZ decontamination is now properly paused when set to disabled.","ru":"Деконтаминация Лёгкой зоны теперь корректно ставится на паузу при отключении."},{"k":"b","lv":1,"en":"Unpausing it will resume the timer at which it was before.","ru":"При снятии паузы таймер продолжится с того же места."},{"k":"b","lv":0,"en":"Decontamination display animation now updates properly if time is edited via plugins.","ru":"Анимация дисплея деконтаминации теперь корректно обновляется, если время меняют плагины."},{"k":"b","lv":0,"en":"Added synchronization for MicroHID movement speed, allowing modders to change it on the server by request.","ru":"Добавлена синхронизация скорости передвижения с MicroHID — модеры могут менять её на сервере."},{"k":"b","lv":0,"en":"Plugins should now be able to reset a glass after it was destroyed by changing its IsBroken status.","ru":"Плагины теперь могут восстанавливать разбитое стекло, меняя его IsBroken."},{"k":"b","lv":0,"en":"VoiceModules now set ServerIsSending to true immediately when the CurrentChannel is set.","ru":"VoiceModules теперь сразу ставят ServerIsSending в true при установке CurrentChannel."},{"k":"b","lv":1,"en":"This fixes the issue of the sender's IsSpeaking property returning false in PlayerReceivingVoiceMessageEvent.","ru":"Это исправляет IsSpeaking отправителя, возвращавший false в PlayerReceivingVoiceMessageEvent."},{"k":"b","lv":0,"en":"The Channel field in the VoiceMessage in the PlayerSendingVoiceMessageEvent will now be passed to CurrentChannel and ValidateReceive, properly reflecting changes made by plugins.","ru":"Поле Channel в VoiceMessage события PlayerSendingVoiceMessageEvent теперь передаётся в CurrentChannel и ValidateReceive — изменения плагинов учитываются."},{"k":"b","lv":1,"en":"Changing the voice channel in PlayerSendingVoiceMessageEvent now automatically flows to PlayerReceivingVoiceMessageEvents.","ru":"Изменение голосового канала в PlayerSendingVoiceMessageEvent теперь автоматически попадает в PlayerReceivingVoiceMessageEvent."},{"k":"b","lv":0,"en":"CurrentChannel will no longer be set if the PlayerSendingVoiceMessageEvent is canceled.","ru":"CurrentChannel больше не устанавливается, если PlayerSendingVoiceMessageEvent отменён."},{"k":"b","lv":0,"en":"Added VisionBlocker layer, which will block SCP-173 and SCP-096 observation mechanics from triggering.","ru":"Добавлен слой VisionBlocker — блокирует срабатывание механик наблюдения SCP-173 и SCP-096."},{"k":"b","lv":1,"en":"You can walk through it, you can shoot through it, you can throw items through it.","ru":"Сквозь него можно ходить, стрелять и бросать предметы."},{"k":"b","lv":0,"en":"Added ScpOnly, which will block everyone except SCPs from passing through these objects.","ru":"Добавлен ScpOnly — через такие объекты могут проходить только SCP."},{"k":"b","lv":1,"en":"You can still shoot and throw items through it as human.","ru":"Люди всё равно могут стрелять и бросать предметы сквозь них."},{"k":"b","lv":0,"en":"Removed unused min-max random generator.","ru":"Удалён неиспользуемый генератор случайных чисел min-max."},{"k":"b","lv":0,"en":"Moved PlayerLeavingEventArgs event to be invoked from within the CustomNetworkManager.","ru":"Событие PlayerLeavingEventArgs теперь вызывается из CustomNetworkManager."},{"k":"b","lv":0,"en":"Added option for server in InteractableToy to differentiate between players search time.","ru":"В InteractableToy добавлена опция сервера для разного времени поиска у игроков."},{"k":"b","lv":0,"en":"Slight optimizations in the backtracking SCP attack base module.","ru":"Небольшие оптимизации модуля «бэктрекинга» в базе атак SCP."},{"k":"b","lv":0,"en":"Tesla Gates no longer deal UniversalDamageHandler.","ru":"Тесла-ворота больше не наносят урон через UniversalDamageHandler."},{"k":"b","lv":1,"en":"Instead, a new TeslaDamageHandler class has been added as a replacement.","ru":"Вместо него добавлен новый класс TeslaDamageHandler."},{"k":"b","lv":0,"en":"Tesla Gates now passes a TriggerReason indicating what triggered them.","ru":"Тесла-ворота теперь передают TriggerReason — причину срабатывания."},{"k":"b","lv":1,"en":"A TriggerReason.Custom value has been added for plugins to utilize freely.","ru":"Добавлено значение TriggerReason.Custom для свободного использования плагинами."},{"k":"b","lv":0,"en":"Removed StructurePositionSync script from all structures.","ru":"Скрипт StructurePositionSync удалён со всех структур."},{"k":"b","lv":0,"en":"Added IWarheadImmuneRole, which indicates roles with a conditional immunity to the warhead, such as SCP-079.","ru":"Добавлен IWarheadImmuneRole — помечает роли с условным иммунитетом к боеголовке (например, SCP-079)."},{"k":"b","lv":0,"en":"Renamed warhead RpcShake to RpcDetonate for better clarity.","ru":"RpcShake боеголовки переименован в RpcDetonate для ясности."},{"k":"b","lv":0,"en":"Added Scp079Camera.GetZoneCameras, which provides a list of all cameras inside a specified zone.","ru":"Добавлен Scp079Camera.GetZoneCameras — возвращает список всех камер в указанной зоне."},{"k":"b","lv":0,"en":"Optimized coordinate lookup in RoomIdentifier.","ru":"Оптимизирован поиск координат в RoomIdentifier."},{"k":"b","lv":0,"en":"Added ItemBase.IsBeingRemoved, set after ItemBase.OnRemoved is called.","ru":"Добавлен ItemBase.IsBeingRemoved — устанавливается после вызова ItemBase.OnRemoved."},{"k":"b","lv":0,"en":"PlayerChang(ing/ed)BadgeVisibility now has NewVisibility set to true when showing a tag.","ru":"В PlayerChang(ing/ed)BadgeVisibility теперь NewVisibility = true, когда тег показывается."},{"k":"b","lv":0,"en":"Added a system to the game that lets you see an outline of specific players or objects locally and sent from the server to clients.","ru":"Добавлена система, позволяющая видеть обводку определённых игроков или объектов — локально или по команде сервера."},{"k":"b","lv":0,"en":"Allows to change Priority, Colour, Thickness, StencilShrink (how sharp the edges should be, with 0 being general object outline), SeeThroughWalls & Fill.","ru":"Можно менять Priority, Colour, Thickness, StencilShrink (резкость краёв, 0 — обычная обводка объекта), SeeThroughWalls и Fill."},{"k":"b","lv":0,"en":"This system uses a custom shader with a custom draw pass to render the top most priority outline for every OutlineEffectController (if it has any active).","ru":"Система использует собственный шейдер с отдельным проходом отрисовки и рисует обводку с наивысшим приоритетом для каждого OutlineEffectController (если у него есть активные)."},{"k":"b","lv":0,"en":"Every controller has its own material that lasts for the controller's lifetime, reusing it until the end. All outlines that are considered fully transparent are also not rendered, saving draw calls.","ru":"У каждого контроллера свой материал на всё время его жизни. Полностью прозрачные обводки не рисуются, что экономит draw call'ы."},{"k":"b","lv":0,"en":"Outlines are objects whose instances belong to single controller. There is a copy constructor, which creates deep copy and increments the ID to a new one, and a clone Clone() method if you create a template, such as one created via Unity serialisation, and then distribute it to all players.","ru":"Обводки — объекты, экземпляры которых принадлежат одному контроллеру. Есть конструктор копирования (глубокая копия с новым ID) и метод Clone() — если вы создаёте шаблон (например, через сериализацию Unity) и раздаёте его всем игрокам."},{"k":"b","lv":0,"en":"Current system allows creating outlines visible to everyone/specific role(s)/specific team with the exception of role(s).","ru":"Можно создавать обводки, видимые всем / определённым ролям / определённой команде за исключением некоторых ролей."},{"k":"b","lv":0,"en":"Outlines also prevent some of the culling of the outline objects, both on the server and client side, to make sure they are visible when they should be through walls.","ru":"Обводки также частично отключают отсечение объектов на сервере и клиенте, чтобы те были видны сквозь стены, когда нужно."},{"k":"b","lv":0,"en":"Outlines on themself cannot be edited in real-time by re-sending data. But there are several modifiers which let you handle these on the client side or send sync values to the client. The current available modifiers are:","ru":"Сами обводки нельзя менять в реальном времени повторной отправкой данных, но есть модификаторы для обработки на клиенте или синхронизации значений. Доступные модификаторы:"},{"k":"b","lv":1,"en":"DistanceBasedModifier for close and distance fade in and out.","ru":"DistanceBasedModifier — появление и затухание вблизи/вдали."},{"k":"b","lv":1,"en":"CurveBasedOutlineModifier to change properties over network time via curves.","ru":"CurveBasedOutlineModifier — изменение свойств по сетевому времени через кривые."},{"k":"b","lv":1,"en":"NetworkedCurveModifier to change the properties via synced float value for evaluation.","ru":"NetworkedCurveModifier — изменение свойств через синхронизированное значение float."},{"k":"b","lv":1,"en":"PlayerStatOutlineModifier to change properties via automatically synced normalised float value of player's StatBase.","ru":"PlayerStatOutlineModifier — изменение свойств через автоматически синхронизируемое нормализованное значение StatBase игрока."},{"k":"b","lv":0,"en":"SCP-1507's teammate visibility through walls now utilizes the outlines system instead of its own.","ru":"Видимость союзников SCP-1507 сквозь стены теперь работает через систему обводок, а не свою собственную."},{"k":"b","lv":0,"en":"Added outline add and outline remove console commands.","ru":"Добавлены консольные команды outline add и outline remove."},{"k":"b","lv":0,"en":"Added Selection-based outline, which allows outline to be visible for specific player(s) only.","ru":"Добавлена обводка по выбору — видна только определённым игрокам."},{"k":"b","lv":0,"en":"Added DisplayKit, a system which allows plugin devs to create Labels/Panels on the player screen.","ru":"Добавлен DisplayKit — система, с помощью которой разработчики плагинов могут выводить надписи/панели на экран игрока."},{"k":"b","lv":0,"en":"Added new setting in the Interface category called \"Custom DisplayKit Elements\" its shown by default but users can hide any elements created by server anytime.","ru":"В категорию «Интерфейс» добавлена настройка «Пользовательские элементы DisplayKit»: по умолчанию включена, но игрок может в любой момент скрыть элементы, созданные сервером."},{"k":"b","lv":0,"en":"Added a new PrimitiveToyType enum, this acts as a replacement from Unity's default PrimitiveType.","ru":"Добавлен новый enum PrimitiveToyType — замена стандартного PrimitiveType из Unity."},{"k":"b","lv":1,"en":"This was necessary in order to add new entries.","ru":"Это было нужно, чтобы добавить новые варианты."},{"k":"b","lv":0,"en":"Added new Primitive Toy types based on popular community request:","ru":"По многочисленным просьбам сообщества добавлены новые типы Primitive Toy:"},{"k":"b","lv":1,"en":"Cone.","ru":"Конус."},{"k":"b","lv":1,"en":"Triangle.","ru":"Треугольник."},{"k":"b","lv":0,"en":"Triangle has multiple subtypes:","ru":"У треугольника несколько подтипов:"},{"k":"b","lv":1,"en":"Note: \"Solid\" variants are visible from both sides, while non-solid ones act as a Planes, with only one side visible.","ru":"Примечание: «Solid»-варианты видны с обеих сторон, обычные работают как плоскость — видна лишь одна сторона."},{"k":"b","lv":1,"en":"Triangle - An \"Equilateral Triangle\", all three sides are equal, 60°.","ru":"Triangle — равносторонний треугольник, все стороны равны, углы 60°."},{"k":"b","lv":1,"en":"TriangleSolid - A variant of \"Triangle\" where both sides are visible.","ru":"TriangleSolid — вариант Triangle, видимый с обеих сторон."},{"k":"b","lv":1,"en":"Triangle90 - A \"Right Isosceles Triangle\", has a right angle (90°), and two equal angles (45°).","ru":"Triangle90 — прямоугольный равнобедренный треугольник: прямой угол (90°) и два угла по 45°."},{"k":"b","lv":1,"en":"Triangle90Solid - A variant of \"Triangle90\" where both sides are visible.","ru":"Triangle90Solid — вариант Triangle90, видимый с обеих сторон."},{"k":"b","lv":0,"en":"Broadcasts will now automatically adjust their vertical position based on whether the Spectator UI is currently visible for spectators.","ru":"Броадкасты теперь автоматически сдвигаются по вертикали в зависимости от того, виден ли интерфейс наблюдателя."},{"k":"b","lv":0,"en":"Added HCZ-EZ Checkpoint B back to Remote Admin's door list.","ru":"КПП B Тяжёлая/Офисная зона возвращён в список дверей Remote Admin."},{"k":"b","lv":0,"en":"Added ability to hide Role intro when spawning players through the Role Management window.","ru":"Добавлена возможность скрывать заставку роли при выдаче роли через окно Role Management."},{"k":"b","lv":1,"en":"You can, of course, replicate this through plugins by using the new RoleSpawnFlags.ShowIntroScreen flag.","ru":"Разумеется, это можно повторить плагином через новый флаг RoleSpawnFlags.ShowIntroScreen."},{"k":"b","lv":0,"en":"warhead_tminus_start_duration config now uses the closest StartScenario.","ru":"Конфиг warhead_tminus_start_duration теперь использует ближайший StartScenario."},{"k":"b","lv":0,"en":"Filmmaker keyframes now present their stored values in a human-readable form.","ru":"Ключевые кадры Filmmaker теперь показывают значения в читаемом виде."},{"k":"b","lv":1,"en":"Most notably, the rotation is now displayed in euler angles instead of quaternions.","ru":"В частности, вращение показано в углах Эйлера, а не кватернионах."},{"k":"b","lv":0,"en":"Hovering over items in the RA Items menu now also display said items' flags, as well as their rarity.","ru":"При наведении на предметы в меню Items в RA теперь видны их флаги и редкость."},{"k":"b","lv":0,"en":"Fixed effect update events not being called when the duration was changed.","ru":"Исправлено: события обновления эффекта не вызывались при изменении длительности."},{"k":"b","lv":0,"en":"Fixed SCP-1344 severing your eyes if dropped before the animation for it actually finished playing.","ru":"Исправлено: SCP-1344 вырывал глаза, если его выбросить до окончания анимации."},{"k":"b","lv":0,"en":"Fixed SCP-096 being able to break doors while they are open.","ru":"Исправлено: SCP-096 мог ломать открытые двери."},{"k":"b","lv":0,"en":"Fixed SCP-244 affecting SCP-106 while in Stalking mode.","ru":"Исправлено: SCP-244 действовал на SCP-106 в режиме Преследования."},{"k":"b","lv":0,"en":"Fixed spectators being able to hear SCP-939's stolen voicelines.","ru":"Исправлено: наблюдатели слышали украденные реплики SCP-939."},{"k":"b","lv":0,"en":"Fixed issue causing health values to appear at zero (or mismatching) while spectating.","ru":"Исправлено: при наблюдении здоровье отображалось нулевым (или неверным)."},{"k":"b","lv":0,"en":"Fixed Human ragdolls not being affected by SeveredHands & SeveredEyes effects.","ru":"Исправлено: на человеческие рэгдоллы не действовали эффекты отрубленных рук и вырванных глаз."},{"k":"b","lv":0,"en":"Fixed issue causing \"Press F to deny further resurrection\" dialog box to stay open indefinitely when spamming the confirmation key.","ru":"Исправлено: окно «Нажмите F, чтобы отказаться от дальнейшего воскрешения» висело бесконечно при спаме клавиши подтверждения."},{"k":"b","lv":0,"en":"Fixed issue allowing melee attacks to hit further away than intended.","ru":"Исправлено: атаки ближнего боя доставали дальше, чем задумано."},{"k":"b","lv":0,"en":"Fixed a bug that prevented SCP selection randomization from being applied correctly when too many players had opted out of SCP.","ru":"Исправлено: рандомизация выбора SCP применялась некорректно, если слишком много игроков отказались играть за SCP."},{"k":"b","lv":0,"en":"Fixed the neck of ragdolls not rotating after dying to SCP-173.","ru":"Исправлено: шея рэгдолла не поворачивалась после смерти от SCP-173."},{"k":"b","lv":0,"en":"Fixed being able to hear the Tantrum sound effects at higher distances than intended.","ru":"Исправлено: звуки Истерики было слышно дальше, чем задумано."},{"k":"b","lv":0,"en":"Fixed custom keycard pickups not displaying custom name tags.","ru":"Исправлено: у выброшенных кастомных карт-ключей не отображалось кастомное имя."},{"k":"b","lv":0,"en":"Fixed cases where you could sabotage your team as SCP-3114 by shattering SCP-2176.","ru":"Исправлено: SCP-3114 мог подставить свою команду, разбив SCP-2176."},{"k":"b","lv":0,"en":"Fixed grenades using the thrower's armor when calculating damage to its victims.","ru":"Исправлено: гранаты учитывали броню бросившего при расчёте урона по жертвам."},{"k":"b","lv":0,"en":"Fixed SCP-3114 being able to break SCP-079's glass by throwing items.","ru":"Исправлено: SCP-3114 мог разбить стекло SCP-079, бросая предметы."},{"k":"b","lv":0,"en":"Fixed Anti-SCP-207's AHP regenerating more than intended preventing death.","ru":"Исправлено: AHP от Anti-SCP-207 восстанавливалось больше, чем задумано, предотвращая смерть."},{"k":"b","lv":0,"en":"Fixed dealing friendly fire damage as SCP-3114 by using snowballs.","ru":"Исправлено: SCP-3114 мог наносить урон по своим снежками."},{"k":"b","lv":0,"en":"Fixed SCP-2176 not locking down doors after the warhead has detonated.","ru":"Исправлено: SCP-2176 не блокировал двери после детонации боеголовки."},{"k":"b","lv":0,"en":"Fixed newly spawned players overwriting the current search coordinator.","ru":"Исправлено: новые игроки перезаписывали текущий координатор поиска."},{"k":"b","lv":0,"en":"Fixed RA REQUEST button bypassing ViewHiddenBadges and ViewHiddenGlobalBadges permissions.","ru":"Исправлено: кнопка REQUEST в RA обходила права ViewHiddenBadges и ViewHiddenGlobalBadges."},{"k":"b","lv":0,"en":"Fixed pauseculling command status not resetting after round restart.","ru":"Исправлено: статус команды pauseculling не сбрасывался после рестарта раунда."},{"k":"b","lv":0,"en":"Fixed TX and RX text displays on the Radio's UI being tiny.","ru":"Исправлено: надписи TX и RX на интерфейсе рации были крошечными."},{"k":"b","lv":0,"en":"Fixed inaccuracies in item viewmodel tracking or camera effects framework.","ru":"Исправлены неточности в отслеживании вьюмоделей предметов и системе эффектов камеры."},{"k":"b","lv":0,"en":"Fixed camera effects not being respected when it comes to interacting with objects.","ru":"Исправлено: эффекты камеры не учитывались при взаимодействии с объектами."},{"k":"b","lv":0,"en":"Fixed Anti-SCP-207's third person model having a transparent cap.","ru":"Исправлено: у модели Anti-SCP-207 от третьего лица была прозрачная крышка."},{"k":"b","lv":0,"en":"Fixed Anti-SCP-207's dropped model having a red color cap.","ru":"Исправлено: у выброшенной Anti-SCP-207 была красная крышка."},{"k":"b","lv":0,"en":"Fixed Anti-SCP-207 not applying the correct weapon debuffs.","ru":"Исправлено: Anti-SCP-207 накладывала неправильные дебаффы оружию."},{"k":"b","lv":0,"en":"Fixed Jailbird ignoring hitmark conditions.","ru":"Исправлено: Jailbird игнорировал условия хитмаркеров."},{"k":"b","lv":0,"en":"Fixed SCP-1509, Jailbird hitmarkers not showing when hitting non-player objects.","ru":"Исправлено: хитмаркеры SCP-1509 и Jailbird не появлялись при ударе по не-игрокам."},{"k":"b","lv":0,"en":"Fixed the HCZ T-Intersection pillars having the incorrect texture.","ru":"Исправлено: у колонн Т-перекрёстка Тяжёлой зоны была неверная текстура."},{"k":"b","lv":0,"en":"Fixed the door frames in the upper part of SCP-127's chamber being incorrectly sized.","ru":"Исправлено: дверные рамы в верхней части камеры SCP-127 были неправильного размера."},{"k":"b","lv":0,"en":"Fixed Piperoom abusable spot via a pipes collision","ru":"Исправлено абузное место в Трубной комнате через коллизию труб."},{"k":"b","lv":0,"en":"Fixed HCZ armory pixel walk on pipes above void.","ru":"Исправлен «пиксельный» проход по трубам над пропастью в оружейной Тяжёлой зоны."},{"k":"b","lv":0,"en":"Fixed the weird floor light in LCZ T-Closet intersections.","ru":"Исправлен странный свет в полу Т-перекрёстков с подсобкой в Лёгкой зоне."},{"k":"b","lv":0,"en":"Definitively fixed HCZ Testroom pillars collisions on all sides.","ru":"Окончательно исправлены коллизии колонн Тестовой комнаты Тяжёлой зоны со всех сторон."},{"k":"b","lv":0,"en":"Fixed HCZ Testroom death pit being too low to prevent rare waterfall room piece clipping through.","ru":"Исправлено: яма смерти в Тестовой комнате была слишком низкой и не мешала редкому пролезанию части комнаты с водопадом."},{"k":"b","lv":0,"en":"Fixed SCP-106 being able to teleport to SCP-079 containment before its unlocked.","ru":"Исправлено: SCP-106 мог телепортироваться в камеру SCP-079 до её открытия."},{"k":"b","lv":0,"en":"Fixed HCZ-T Pipes intersection abusable spot near locker and the blue foil cover.","ru":"Исправлено абузное место у шкафчика и синей плёнки на Т-перекрёстке с трубами в Тяжёлой зоне."},{"k":"b","lv":0,"en":"Fixed Warhead Silo staircases and firing chamber having no collisions.","ru":"Исправлено: у лестниц и пусковой камеры Шахты боеголовки не было коллизий."},{"k":"b","lv":0,"en":"Fixed Warhead Silo staircases being misaligned.","ru":"Исправлено: лестницы Шахты боеголовки были смещены."},{"k":"b","lv":0,"en":"Fixed textures on the Warhead Silo firing chamber, staircases, and platform.","ru":"Исправлены текстуры пусковой камеры, лестниц и платформы Шахты боеголовки."},{"k":"b","lv":0,"en":"Fixed forklift colliders allowing players to jump on wheels and then on the model itself.","ru":"Исправлено: коллайдеры погрузчика позволяли запрыгнуть на колёса, а затем на саму модель."},{"k":"b","lv":0,"en":"Fixed AttachmentParam.PreventReload not working for CustomPlayerEffects.","ru":"Исправлено: AttachmentParam.PreventReload не работал для CustomPlayerEffects."},{"k":"b","lv":0,"en":"Fixed exiting TemporaryHazard not triggering Exit methods if the hazard was destroyed via explosion.","ru":"Исправлено: выход из TemporaryHazard не вызывал методы Exit, если опасность была уничтожена взрывом."},{"k":"b","lv":0,"en":"Fixed ElevatorChamber._floorDoors not being properly set up if accessed early enough.","ru":"Исправлено: ElevatorChamber._floorDoors не настраивался, если обратиться к нему слишком рано."},{"k":"b","lv":0,"en":"Fixed badge being shown even when PlayerInfoArea does not declare badges should be shown.","ru":"Исправлено: бейдж показывался, даже если PlayerInfoArea не разрешает показывать бейджи."},{"k":"b","lv":0,"en":"Fixed exception thrown when ElevatorChamber.CurrentRoom called too early.","ru":"Исправлено исключение при слишком раннем вызове ElevatorChamber.CurrentRoom."},{"k":"b","lv":0,"en":"Fixed exception thrown and disconnection when AnomalousTarget effect instance is not found.","ru":"Исправлены исключение и отключение, когда экземпляр эффекта AnomalousTarget не найден."},{"k":"b","lv":0,"en":"Fixed exception thrown when plugin set the Player property to null in generator activating.","ru":"Исправлено исключение, когда плагин ставил свойство Player в null при активации генератора."},{"k":"b","lv":0,"en":"Fixed exception thrown when SubtitleParts was null.","ru":"Исправлено исключение, когда SubtitleParts был null."},{"k":"b","lv":0,"en":"Fixed exception thrown in QueryProcessor when an unauthenticated players left.","ru":"Исправлено исключение в QueryProcessor при выходе неавторизованного игрока."},{"k":"b","lv":0,"en":"Fixed exception thrown in the client when the player escaped.","ru":"Исправлено исключение на клиенте при побеге игрока."},{"k":"b","lv":0,"en":"Fixed exception thrown by LiteNetLib when client disconnected from the server, or the server refused the connection.","ru":"Исправлено исключение LiteNetLib при отключении клиента от сервера или отказе сервера в подключении."},{"k":"b","lv":0,"en":"Fixed exception when accessing Player IP address after they left.","ru":"Исправлено исключение при обращении к IP игрока после его выхода."},{"k":"b","lv":0,"en":"Fixed OnScp106TeleportedPlayer being invoked even if the target is the last player alive and therefore instantly killed.","ru":"Исправлено: OnScp106TeleportedPlayer вызывался, даже если цель — последний живой игрок и сразу погибает."},{"k":"b","lv":0,"en":"Fixed getting ServerSpawnFlags log error for server-only properties.","ru":"Исправлена ошибка в логе ServerSpawnFlags для серверных свойств."},{"k":"b","lv":0,"en":"Fixed Scp330Bag.ServerProcessPickup bag parameter is null when they don't have a bag.","ru":"Исправлено: в Scp330Bag.ServerProcessPickup параметр bag был null, если у игрока нет мешочка."},{"k":"b","lv":0,"en":"Fixed wave pause states not resetting across rounds.","ru":"Исправлено: состояния паузы волн не сбрасывались между раундами."},{"k":"b","lv":0,"en":"Fixed PreviousOwner property not assigned for ammo pickups.","ru":"Исправлено: свойство PreviousOwner не задавалось для подобранных патронов."},{"k":"b","lv":0,"en":"Fixed attacker not being set when a door gets damaged by SCP-1507 or a Particle Disruptor.","ru":"Исправлено: атакующий не указывался, если дверь повреждена SCP-1507 или Дисраптором."},{"k":"b","lv":0,"en":"Fixed issues where FastResources wouldn't load ScriptableObjects derived from other classes.","ru":"Исправлено: FastResources не загружал ScriptableObject'ы, унаследованные от других классов."},{"k":"b","lv":0,"en":"Fixed decontamination disable command not working correctly.","ru":"Исправлено: команда отключения деконтаминации работала некорректно."},{"k":"b","lv":0,"en":"Fixed \"initialising procedure pb...\" text being inside the decon display.","ru":"Исправлено: текст «initialising procedure pb...» был внутри дисплея деконтаминации."},{"k":"b","lv":0,"en":"Fixed \"please evacuate\" text being partially inside the display.","ru":"Исправлено: текст «please evacuate» частично залезал внутрь дисплея."},{"k":"b","lv":0,"en":"Fixed scale command returning a checkmark even when the command failed.","ru":"Исправлено: команда scale возвращала галочку даже при ошибке."},{"k":"b","lv":0,"en":"Fixed CustomFog not having Serializable attribute.","ru":"Исправлено: у CustomFog не было атрибута Serializable."},{"k":"b","lv":0,"en":"Fixed Skybox prefab using old HolidayMaterialReplacer fileId.","ru":"Исправлено: префаб скайбокса использовал старый fileId HolidayMaterialReplacer."},{"k":"b","lv":0,"en":"Fixed InventoryExtensions.OnItemRemoved firing twice when jailbird ran out of charges.","ru":"Исправлено: InventoryExtensions.OnItemRemoved срабатывал дважды, когда у Jailbird кончались заряды."},{"k":"b","lv":0,"en":"Fixed CustomNetworkManager not invoking OnClientStart event when client started.","ru":"Исправлено: CustomNetworkManager не вызывал событие OnClientStart при запуске клиента."},{"k":"b","lv":0,"en":"Fixed Tesla Gate being at 0, 0, 0 when spawned by plugins.","ru":"Исправлено: Тесла-ворота, созданные плагинами, появлялись в точке 0, 0, 0."},{"k":"b","lv":0,"en":"Fixed changescale, setgravity commands not recognizing player names with spaces.","ru":"Исправлено: команды changescale и setgravity не распознавали имена игроков с пробелами."}];
